import { EventEmitter } from "common/typedEventEmitter.ts";
import { Optional } from "common/serialisation/optional.ts";

export abstract class Storer<Value> {
  /** Retrieve the value from storage */
  abstract load(key: string): Optional<Value>;
  /**
   * Save the value to storage.
   * @retval `false` iff there are no changes. i.e. the result of `load()` won't change due to this call
   */
  abstract save(key: string, value: Optional<Value>, prevValue: Optional<Value>): boolean;
}

class CachedStore<Value> {
  constructor(readonly key: string, private readonly storer: Storer<Value>) {}

  readonly #cache = new Optional<Value>(false);

  setValue(value: Value) {
    if (this.storer.save(this.key, new Optional(true, value), this.#cache)) {
      this.#cache.value = value;
      return true;
    }
    return false;
  }

  getValue(): Optional<Value> {
    return this.#cache.getOrSetComputed(() => this.storer.load(this.key));
  }

  clearValue() {
    if (this.storer.save(this.key, new Optional(false), this.#cache)) {
      this.#cache.clear();
      return true;
    }
    return false;
  }
}

type AnyStorer = Storer<any>;

export interface Storers {
  [key: string]: AnyStorer | Storers;
}

export type KeyOf<S extends Storers> = Extract<
  {
    [Key in keyof S & string]: S[Key] extends AnyStorer ? Key
      : S[Key] extends Storers ? `${Key}.${KeyOf<S[Key]>}`
      : never;
  }[keyof S & string],
  string
>;

export type StorerOf<S extends Storers, Key extends string> = Key extends `${infer Head}.${infer Tail}`
  ? Head extends keyof S ? S[Head] extends Storer<infer Value> ? Value
    : S[Head] extends Storers ? StorerOf<S[Head], Tail>
    : never
  : never
  : Key extends keyof S ? S[Key] extends Storer<any> ? S[Key]
    : never
  : never;

export type ValueOf<S extends Storers, Key extends string> = StorerOf<S, Key> extends Storer<infer Value> ? Value : never;

type ManagerEvents<S extends Storers> = {
  change: Set<KeyOf<S>>;
};

type CachedStorers<S extends Storers> = {
  [K in keyof S]: S[K] extends Storer<infer V> ? CachedStore<V> : S[K] extends Storers ? CachedStorers<S[K]> : never;
};

export abstract class Manager<S extends Storers> extends EventEmitter<ManagerEvents<S>> {
  readonly #store: CachedStorers<S>;
  #batchDepth = 0;
  #batchChange = new Set<KeyOf<S>>();

  protected constructor(store: S) {
    super();
    this.#store = Manager.cached(store);
  }

  private static cached<S extends Storers>(store: S, ...prefix: string[]): CachedStorers<S> {
    return Object.fromEntries(
      Object.entries(store).map(([k, v]) => {
        if (v instanceof Storer) return [k, new CachedStore([...prefix, k].join("."), v)];
        return [k, Manager.cached(v, ...prefix, k)];
      }),
    );
  }

  get<Key extends KeyOf<S>>(key: Key): Optional<ValueOf<S, Key>> {
    return this.getStoreValue(key).getValue();
  }

  set<Key extends KeyOf<S>>(key: Key, value: ValueOf<S, Key>) {
    if (this.getStoreValue(key).setValue(value)) this.change(key);
  }

  remove<Key extends KeyOf<S>>(key: Key) {
    if (this.getStoreValue(key).clearValue()) this.change(key);
  }

  /** Delays changed events until action has completed */
  batch(action: () => void) {
    ++this.#batchDepth;
    try {
      action();
    } finally {
      this.finishBatch();
    }
  }

  private finishBatch() {
    --this.#batchDepth;
    if (this.#batchDepth === 0 && this.#batchChange.size > 0) {
      this.emit("change", this.#batchChange);
      this.#batchChange.clear();
    }
  }

  private change(key: KeyOf<S>) {
    this.#batchChange.add(key);
    if (this.#batchDepth > 0) {
      return;
    }
    this.emit("change", this.#batchChange);
    this.#batchChange.clear();
  }

  private getStoreValue<K extends KeyOf<S>>(key: K): CachedStore<ValueOf<S, K>> {
    const storer = Manager.findStorer(this.#store, key.split("."));
    if (storer === undefined) throw new Error(`Unknown manager key: ${key}`);
    return storer as CachedStore<ValueOf<S, K>>;
  }

  private static findStorer<S extends Storers>(store: CachedStorers<S>, parts: readonly string[]): CachedStore<any> | undefined {
    const [head, ...tail] = parts;
    if (head === undefined) return;

    const child = store[head];
    if (child instanceof CachedStore) return tail.length === 0 ? child : undefined;
    if (child !== undefined) return this.findStorer(child as CachedStorers<Storers>, tail);
  }
}
