// deno-lint-ignore-file no-explicit-any
import { EventEmitter } from "common/typedEventEmitter.ts";
import { Semaphore } from "common/async.ts";

export const serialisationType = Symbol("SerialisationType");

type DefaultUint8Array = ReturnType<Uint8Array["slice"]>;

//@ts-ignore This is required to work in the browser, where Symbol.dispose isn't defined yet
Symbol.dispose ??= Symbol.for("Symbol.dispose");

/**
 * The static interface for serialisable classes
 */
export interface SerialisableConstructor<S extends Serialisable<any>> {
  readonly [serialisationType]: string;
  /** Prefer SerialisationReader.peek */
  peek(data: SerialisationReader, offset?: number): Deserialised<S>;
  peek(data: SerialisationReader, offset: number, abort: AbortSignal): Promise<Deserialised<S>>;
  new (value: RemoveOneSerialisable<S>): S;
  new (...any: any[]): S;
}

/**
 * Interface for serialisable instances
 */
export interface Serialisable<T> {
  serialise(data: Serialisation): void;
  readonly serialisedLength: number;
  value: T;
}

export interface Deserialised<T extends Serialisable<any>> {
  readonly deserialisedLength: number;
  readonly serialisable: T;
}

export class DeserialiseError extends Error {
  constructor() {
    super("Not enough data in serialisation");
  }
}

// Incorrect data. Can occur during deserialise/construction/setting
export class SerialisationError extends Error {}

export interface SerialisationReader {
  readonly length: number;

  peek(bytes: number, offset?: number): DefaultUint8Array;
  peek(bytes: number, offset: number, abort: AbortSignal): Promise<DefaultUint8Array>;
  peek<T extends Serialisable<any>>(serialisable: SerialisableConstructor<T>, offset?: number): Deserialised<T>;
  peek<T extends Serialisable<any>>(serialisable: SerialisableConstructor<T>, offset: number, abort?: AbortSignal): Promise<Deserialised<T>>;

  readonly aborted: boolean;
  abort(): void;
  close(): void;

  indexOfByte(byte: number, offset?: number): number;
  indexOfByte(byte: number, offset: number, abort: AbortSignal): Promise<number>;

  read(bytes: number, offset?: number): DefaultUint8Array;
  read(bytes: number, offset: number, abort: AbortSignal): Promise<DefaultUint8Array>;
  readAll(): DefaultUint8Array;

  deserialise<T extends Serialisable<any>>(serialisable: SerialisableConstructor<T>, offset?: number): Deserialised<T>;
  deserialise<T extends Serialisable<any>>(serialisable: SerialisableConstructor<T>, offset: number, abort?: AbortSignal): Promise<Deserialised<T>>;

  [Symbol.dispose](): void;
}

export type SerialisationTransform = {
  writable: WritableStream<Uint8Array>;
  reader: SerialisationReader;
};

/**
 * Basically a wrapper for Uint8Array that allows for reallocation.
 * Has a buffer (read Uint8Array) and an internal buffer (the Uint8Array's ArrayBuffer)
 */
export class Serialisation {
  private buffer: DefaultUint8Array;

  static serialiseToBuffer(serialisable: Serialisable<any>) {
    return new Serialisation(serialisable).buffer;
  }

  static deserialiseFromBuffer<T>(serialisable: SerialisableConstructor<Serialisable<T>>, buffer: DefaultUint8Array) {
    using reader = new Serialisation(buffer).getReaderNow()!;
    return reader.deserialise(serialisable).serialisable.value;
  }

  constructor(buffer?: DefaultUint8Array);
  constructor(serialisable: Serialisable<any>);
  constructor(serialisation: DefaultUint8Array | Serialisable<any> = new Uint8Array()) {
    if (serialisation instanceof Uint8Array) {
      this.buffer = serialisation;
    } else {
      this.buffer = new Uint8Array();
      serialisation.serialise(this);
    }
  }

  private readonly readSemaphore = new Semaphore();

  static readonly Reader = class Reader implements SerialisationReader {
    constructor(private readonly serialisation: Serialisation, private readonly exit: () => void) {}
    private get buffer() {
      return this.serialisation.buffer;
    }
    private get events() {
      return this.serialisation.events;
    }

    get length() {
      return this.buffer.length;
    }

    private readonly aborter = new AbortController();
    #aborted = false;
    get aborted() {
      return this.#aborted;
    }

    abort(reason?: unknown) {
      this.#aborted = true;
      this.aborter.abort(reason);
    }

    close() {
      this.#aborted = false;
      this.aborter.abort();
    }

    readAll() {
      return this.read(this.buffer.length, 0);
    }

    indexOfByte(byte: number, offset?: number): number;
    indexOfByte(byte: number, offset: number, abort: AbortSignal): Promise<number>;
    indexOfByte(byte: number, offset = 0, abort?: AbortSignal): number | Promise<number> {
      if (abort === undefined) {
        return this.buffer.indexOf(byte, offset);
      }
      return new Promise((go, no) => {
        const signal = AbortSignal.any([abort, this.aborter.signal]);
        const onAbort = () => {
          signal.removeEventListener("abort", onAbort);
          this.events.off("extend", onExtend);
          no(new DeserialiseError());
        };
        const onExtend = (event: CustomEvent<number>) => {
          const index = this.buffer.indexOf(byte, this.buffer.length - event.detail);
          if (index !== -1) {
            signal.removeEventListener("abort", onAbort);
            this.events.off("extend", onExtend);
            go(index);
          }
        };
        signal.addEventListener("abort", onAbort);
        this.events.on("extend", onExtend);
        onExtend(new CustomEvent<number>("extend", { detail: this.buffer.length - offset }));
        if (signal.aborted) {
          onAbort();
        }
      });
    }

    peek(bytes: number, offset?: number): DefaultUint8Array;
    peek(bytes: number, offset: number, abort: AbortSignal): Promise<DefaultUint8Array>;
    peek<T extends Serialisable<any>>(serialisable: SerialisableConstructor<T>, offset?: number): Deserialised<T>;
    peek<T extends Serialisable<any>>(serialisable: SerialisableConstructor<T>, offset: number, abort?: AbortSignal): Promise<Deserialised<T>>;
    peek(description: number | SerialisableConstructor<Serialisable<any>>, offset = 0, abort?: AbortSignal) {
      return this.peekOrRead(true, description as any, offset, abort) as any;
    }

    read(bytes: number, offset?: number): DefaultUint8Array;
    read(bytes: number, offset: number, abort: AbortSignal): Promise<DefaultUint8Array>;
    read<T extends Serialisable<any>>(serialisable: SerialisableConstructor<T>, offset?: number): Deserialised<T>;
    read<T extends Serialisable<any>>(serialisable: SerialisableConstructor<T>, offset: number, abort?: AbortSignal): Promise<Deserialised<T>>;
    read(description: number | SerialisableConstructor<Serialisable<any>>, offset = 0, abort?: AbortSignal) {
      return this.peekOrRead(false, description as any, offset, abort) as any;
    }

    private peekOrRead(peek: boolean, bytes: number, offset?: number): DefaultUint8Array;
    private peekOrRead(peek: boolean, bytes: number, offset: number, abort: AbortSignal): Promise<DefaultUint8Array>;
    private peekOrRead<T extends Serialisable<any>>(peek: boolean, serialisable: SerialisableConstructor<T>, offset?: number): Deserialised<T>;
    private peekOrRead<T extends Serialisable<any>>(
      peek: boolean,
      serialisable: SerialisableConstructor<T>,
      offset: number,
      abort?: AbortSignal,
    ): Promise<Deserialised<T>>;
    private peekOrRead(peek: boolean, description: number | SerialisableConstructor<Serialisable<any>>, offset = 0, abort?: AbortSignal) {
      if (typeof description !== "number") {
        if (abort === undefined) {
          const ret = description.peek(this, offset);
          if (!peek) this.advance(offset + ret.deserialisedLength);
          return ret;
        }

        return description.peek(this, offset, AbortSignal.any([abort, this.aborter.signal])).then((ret) => {
          if (!peek) this.advance(offset + ret.deserialisedLength);
          return ret;
        });
      }
      if (offset < 0 || isNaN(offset)) throw new RangeError("offset out of range");
      if (description < 0 || isNaN(description)) throw new RangeError("bytes out of range");
      if (abort === undefined) {
        if (this.buffer.buffer.byteLength < this.buffer.byteOffset + offset + description) {
          throw new DeserialiseError();
        }
        const ret = new Uint8Array(this.buffer.buffer, this.buffer.byteOffset + offset, description);
        if (!peek) this.advance(offset + description);
        return ret;
      } else {
        return new Promise<DefaultUint8Array>((go, no) => {
          const signal = AbortSignal.any([abort, this.aborter.signal]);
          const onAbort = () => {
            signal.removeEventListener("abort", onAbort);
            this.events.off("extend", onExtend);
            no(new DeserialiseError());
          };
          const onExtend = () => {
            if (this.buffer.buffer.byteLength >= this.buffer.byteOffset + offset + description) {
              signal.removeEventListener("abort", onAbort);
              this.events.off("extend", onExtend);
              const ret = new Uint8Array(this.buffer.buffer, this.buffer.byteOffset + offset, description);
              if (!peek) this.advance(offset + description);
              go(ret);
            }
          };
          signal.addEventListener("abort", onAbort);
          this.events.on("extend", onExtend);
          onExtend();
          if (signal.aborted) {
            onAbort();
          }
        });
      }
    }

    private advance(count: number) {
      this.serialisation.buffer = new Uint8Array(
        this.buffer.buffer,
        this.buffer.byteOffset + count,
        this.buffer.byteLength - count,
      );
      this.events.emit("advance", count);
    }

    deserialise<T extends Serialisable<any>>(serialisable: SerialisableConstructor<T>, offset?: number): Deserialised<T>;
    deserialise<T extends Serialisable<any>>(serialisable: SerialisableConstructor<T>, offset: number, abort?: AbortSignal): Promise<Deserialised<T>>;
    deserialise<T extends Serialisable<any>>(serialisable: SerialisableConstructor<T>, offset = 0, abort?: AbortSignal) {
      if (abort === undefined) {
        const s = serialisable.peek(this, offset);
        this.read(s.deserialisedLength, offset);
        return s;
      }
      return serialisable.peek(this, offset, AbortSignal.any([abort, this.aborter.signal])).then((s) => {
        this.read(s.deserialisedLength, offset);
        return s;
      });
    }

    [Symbol.dispose]() {
      this.exit();
    }
  };

  get size() {
    return this.buffer.byteLength;
  }

  async getReader() {
    const delayExit = Promise.withResolvers<void>();
    const reader = new Serialisation.Reader(this, delayExit.resolve);
    return (await this.readSemaphore.call(() => reader, delayExit.promise))[0];
  }

  getReaderNow() {
    if (this.readSemaphore.locked) {
      return undefined;
    }
    const delayExit = Promise.withResolvers<void>();
    this.readSemaphore.call(() => {}, delayExit.promise);
    return new Serialisation.Reader(this, delayExit.resolve);
  }

  /**
   * Reads from the start of the buffer without advancing
   * @param bytes The byte length of the peek
   * @param offset The offset into the buffer to start peeking
   * @returns The peeked memory
   * @throws DeserialseError when there is not enough bytes available
   */
  peek(bytes: number, offset = 0) {
    if (offset < 0 || isNaN(offset)) throw new RangeError("offset out of range");
    if (bytes < 0 || isNaN(bytes)) throw new RangeError("bytes out of range");
    if (this.buffer.buffer.byteLength < this.buffer.byteOffset + offset + bytes) {
      throw new DeserialiseError();
    }
    return new Uint8Array(this.buffer.buffer, this.buffer.byteOffset + offset, bytes);
  }

  /**
   * Ensures there is enough room at the end of the internal buffer for an expansion
   * @param length Required byte length for the expansion
   * @note Reallocates the internal buffer if required, detaching itself from previously returned buffers
   */
  expand(length: number) {
    if (length < 0 || isNaN(length)) throw new RangeError("length out of range");
    if (this.buffer.buffer.byteLength >= this.buffer.byteOffset + this.buffer.byteLength + length) {
      return;
    }

    const old = this.buffer;
    this.buffer = new Uint8Array(old.byteLength + length);
    this.buffer.set(old);
    this.buffer = new Uint8Array(this.buffer.buffer, 0, this.buffer.byteLength - length);
  }

  /**
   * Ensures there is enough room at the end of the buffer for an extension
   * @param length Required byte length for extension
   * @returns The extension
   * @note Reallocates the internal buffer, detaching itself from previously returned buffers
   */
  extend(length: number) {
    this.expand(length);
    this.buffer = new Uint8Array(this.buffer.buffer, this.buffer.byteOffset, this.buffer.byteLength + length);
    return {
      value: new Uint8Array(this.buffer.buffer, this.buffer.byteOffset + this.buffer.byteLength - length),
      [Symbol.dispose]: () => {
        this.events.emit("extend", length);
      },
    };
  }

  stream() {
    return new ReadableStream<DefaultUint8Array>({
      start: (controller) => {
        controller.enqueue(this.buffer);
        controller.close();
      },
    });
  }

  events = new EventEmitter<{
    advance: number;
    extend: number;
  }>();

  get readable() {
    const getReader = this.getReader();
    let onExtend!: () => void;
    return new ReadableStream<DefaultUint8Array>({
      start: async (controller) => {
        const reader = await getReader;
        controller.enqueue(reader.readAll());
        onExtend = () => {
          controller.enqueue(reader.readAll());
        };
        this.events.on("extend", onExtend);
      },
      cancel: () => {
        getReader.then((reader) => reader[Symbol.dispose]());
        this.events.off("extend", onExtend);
      },
    });
  }

  get writable() {
    return new WritableStream<Uint8Array>({
      write: (chunk) => {
        using extension = this.extend(chunk.length);
        extension.value.set(chunk);
      },
    });
  }

  private transformWritable(reader: SerialisationReader, highWaterMark?: number) {
    return new WritableStream<Uint8Array>({
      write: async (chunk) => {
        if (highWaterMark !== undefined) {
          while (reader.length > highWaterMark) {
            await new Promise((go) => {
              this.events.on("advance", go);
            });
          }
        }
        using extension = this.extend(chunk.length);
        extension.value.set(chunk);
      },
      close: () => {
        reader.close();
      },
      abort: () => {
        reader.abort();
      },
    });
  }

  getTransform(highWaterMark?: number): Promise<SerialisationTransform> {
    return this.getReader().then((reader) => {
      return {
        writable: this.transformWritable(reader, highWaterMark),
        reader,
      };
    });
  }

  getTransformNow(highWaterMark?: number): SerialisationTransform | undefined {
    const reader = this.getReaderNow();
    if (reader === undefined) {
      return undefined;
    }

    return {
      writable: this.transformWritable(reader, highWaterMark),
      reader,
    };
  }
}

export type RemoveOneStatic<S extends SerialisableConstructor<Serialisable<any>>> = S extends SerialisableConstructor<infer T> ? T : never;

export type RemoveOneSerialisable<S extends Serialisable<any>> = S extends Serialisable<infer T> ? T : never;

export type RemoveOneStaticSerialisable<S extends SerialisableConstructor<Serialisable<any>>> = S extends SerialisableConstructor<Serialisable<infer T>> ? T
  : never;

export type AddStaticMembers<T extends Record<any, Serialisable<any>>> = {
  [K in keyof T]: SerialisableConstructor<T[K]>;
};

export type AddSerialisableMembers<S extends Record<any, any>> = {
  [K in keyof S]: Serialisable<S[K]>;
};

export type AddStaticSerialisableMembers<S extends Record<any, any>> = {
  [K in keyof S]: SerialisableConstructor<Serialisable<S[K]>>;
};

export type RemoveStaticMembers<S extends Record<any, SerialisableConstructor<Serialisable<S>>>> = {
  [K in keyof S]: RemoveOneStatic<S[K]>;
};

export type RemoveSerialisableMembers<S extends Record<any, Serialisable<any>>> = {
  [K in keyof S]: RemoveOneSerialisable<S[K]>;
};

export type RemoveStaticSerialisableMembers<S extends Record<any, SerialisableConstructor<Serialisable<any>>>> = {
  [K in keyof S]: RemoveOneStaticSerialisable<S[K]>;
};

export type AddStaticTuple<T extends Serialisable<any>[]> = {
  [K in keyof T]: SerialisableConstructor<T[K]>;
};

export type AddSerialisableTuple<V extends any[]> = {
  [K in keyof V]-?: Serialisable<V[K]>;
};

export type RemoveStaticTuple<S extends readonly SerialisableConstructor<Serialisable<any>>[]> = {
  -readonly [K in keyof S]: RemoveOneStatic<S[K]>;
};

export type RemoveSerialisableTuple<V extends readonly Serialisable<any>[]> = {
  -readonly [K in keyof V]: RemoveOneSerialisable<V[K]>;
};

export type RemoveStaticSerialisableTuple<S extends SerialisableConstructor<Serialisable<any>>[]> = {
  [K in keyof S]: RemoveOneStaticSerialisable<S[K]>;
};
