// deno-lint-ignore-file ban-types
export type TypeString =
  | "undefined"
  | "object"
  | "boolean"
  | "number"
  | "bigint"
  | "string"
  | "symbol"
  | "function"
  | "unknown";

export type TypeMap<T extends TypeString> = T extends "undefined" ? undefined
  : T extends "object" ? {} | null
  : T extends "boolean" ? boolean
  : T extends "number" ? number
  : T extends "bigint" ? bigint
  : T extends "string" ? string
  : T extends "symbol" ? symbol
  : T extends "function" ? Function
  : T extends "unknown" ? unknown
  : never;

export function hasProperty<K extends string>(key: K) {
  return function <O extends object>(obj: O): obj is O & { [L in K]: unknown } {
    return key in obj;
  };
}

export function isValue<const V>(value: V) {
  return function (u: unknown): u is V {
    return u === value;
  };
}

export function isUnknown(_u: unknown): _u is unknown {
  return true;
}

export function isType<T extends TypeString>(type: T) {
  if (type === "unknown") {
    return isUnknown as (u: unknown) => u is TypeMap<T>;
  }
  return function (u: unknown): u is TypeMap<T> {
    // deno-lint-ignore valid-typeof
    return typeof u === type;
  };
}

export function isObject(u: unknown): u is object & {} {
  return isType("object")(u) && u !== null;
}

export function isValueOf<T extends object>(e: T) {
  return (token: unknown): token is T[keyof T] => {
    return Object.values(e).includes(token as T[keyof T]);
  };
}

export function isInstanceOf<T>(type: abstract new (...args: any[]) => T) {
  return function (u: unknown): u is T {
    return u instanceof type;
  };
}

export function isArray(u: unknown): u is unknown[] {
  return Array.isArray(u);
}

export function isPromiseLike<T>(val: T | PromiseLike<T>): val is PromiseLike<T> {
  if ((typeof val === "object" && val !== null || typeof val === "function") && "then" in val && typeof val.then === "function") {
    val satisfies PromiseLike<T>;
    return true;
  }
  return false;
}

export type Predicate<U, T extends U> = (u: U) => u is T;

export function conditionallyConforms<U, T1 extends U, T2 extends T1>(predicate1: Predicate<U, T1>, predicate2: Predicate<T1, T2>) {
  return function (u: U): u is T2 | U {
    return !predicate1(u) || predicate2(u);
  };
}

export function propertyConforms<K extends string, T>(key: K, predicate: Predicate<unknown, T>) {
  return function <O extends object & { [L in K]: unknown }>(obj: O): obj is O & { [L in K]: T } {
    return predicate(obj[key]);
  };
}

export function hasConformingProperty<K extends string, T>(key: K, predicate: Predicate<unknown, T>) {
  return function <O extends object>(obj: O): obj is O & { [L in K]: T } {
    return hasProperty(key)(obj) && predicate(obj[key]);
  };
}

export function hasTypedProperty<K extends string, T extends TypeString>(key: K, type: T) {
  return function <O extends object>(o: O): o is O & { [L in K]: TypeMap<T> } {
    return hasConformingProperty(key, isType(type))(o);
  };
}

export function hasInstancedProperty<K extends string, T>(key: K, type: new () => T) {
  return function <O extends object>(o: O): o is O & { [L in K]: T } {
    return hasConformingProperty(key, isInstanceOf(type))(o);
  };
}

export function isConformingArray<T>(predicate: Predicate<unknown, T>) {
  return function (u: unknown): u is T[] {
    return isArray(u) && u.every(predicate);
  };
}

export function isConformingMap<k, v>(predicateKey: Predicate<unknown, k>, predicateValue: Predicate<unknown, v>) {
  return function (u: unknown): u is Map<k, v> {
    return isInstanceOf(Map)(u) && isConformingArray(isConformingTuple(predicateKey, predicateValue))([...u.entries()]);
  };
}

type OptionalTypeString = `?${TypeString}`;

export type ObjectDescriptorMember = Predicate<unknown, any> | OptionalProperty<Predicate<unknown, any>> | TypeString | OptionalTypeString;

export interface ObjectDescriptor extends Record<string, ObjectDescriptorMember | ObjectDescriptor> {}

function isOptionalTypeString(t: TypeString | OptionalTypeString): t is OptionalTypeString {
  return t[0] === "?";
}

function extractTypeString<T extends TypeString>(t: `?${T}`): T {
  return t.slice(1) as T;
}

type ExtractTypeString<T> = T extends `?${infer U extends TypeString}` ? U : never;

// Get the Type that an ObjectDescriptor describes
export type PredicateDomain<T> = T extends Predicate<unknown, infer To> ? To
  : T extends TypeString ? TypeMap<T>
  : T extends Record<string, ObjectDescriptorMember | ObjectDescriptor> ?
      & {
        [
          P in Extract<
            keyof T,
            { [P in keyof T]: T[P] extends OptionalTypeString ? never : T[P] extends OptionalProperty<Predicate<unknown, any>> ? never : P }[keyof T]
          >
        ]: PredicateDomain<T[P]>;
      }
      & {
        [
          P in Extract<
            keyof T,
            {
              [P in keyof T]: T[P] extends OptionalTypeString ? P : T[P] extends OptionalProperty<Predicate<unknown, any>> ? P : never;
            }[keyof T]
          >
        ]?: T[P] extends OptionalProperty<infer Q extends Predicate<unknown, any>> ? PredicateDomain<Q> : PredicateDomain<ExtractTypeString<T[P]>>;
      }
  : never;

export class OptionalProperty<P extends Predicate<unknown, any>> {
  constructor(readonly predicate: P) {}
}

export function isConformingObject<R extends ObjectDescriptor>(predicates: R) {
  type P = PredicateDomain<R>;

  return function (u: unknown): u is P {
    if (!isObject(u)) {
      return false;
    }
    for (const key in predicates) {
      const predicate = predicates[key]!;
      if (typeof predicate === "string") {
        if (isOptionalTypeString(predicate)) {
          if (hasProperty(key)(u) && !isType(extractTypeString(predicate))(u[key])) {
            return false;
          }
        } else if (!hasTypedProperty(key, predicate)(u)) {
          return false;
        }
      } else if (predicate instanceof OptionalProperty) {
        if (hasProperty(key)(u) && !predicate.predicate(u[key])) {
          return false;
        }
      } else if (typeof predicate === "function") {
        if (!hasConformingProperty(key, predicate)(u)) {
          return false;
        }
      } else if (!hasConformingProperty(key, isConformingObject(predicate))(u)) {
        return false;
      }
    }
    return true;
  };
}

export function hasTypedArrayProperty<K extends string, T extends TypeString>(key: K, type: T) {
  type P<O extends object> =
    & O
    & {
      [L in K]: TypeMap<T>[];
    };

  return function <O extends object>(obj: O): obj is P<O> {
    return hasConformingProperty(key, isConformingArray(isType(type)))(obj);
  };
}

export function isConformingTuple<T extends Predicate<unknown, any>[]>(...predicates: T) {
  return function (u: unknown): u is { [i in keyof T]: T[i] extends Predicate<unknown, infer S> ? S : never } {
    return isArray(u) && u.length === predicates.length && predicates.every((predicate, index) => {
      return predicate(u[index]);
    });
  };
}

export function hasConformingKeys<T extends string | number | symbol>(predicate: Predicate<unknown, T>) {
  return function <O extends object>(obj: O): obj is O & Record<T, unknown> {
    for (const key in obj) {
      if (!predicate(key)) {
        return false;
      }
    }
    return true;
  };
}

export function hasConformingProperties<T>(predicate: Predicate<unknown, T>) {
  return function <O extends object>(obj: O): obj is O & Record<string, T> {
    for (const key in obj) {
      if (!hasConformingProperty(key, predicate)(obj)) {
        return false;
      }
    }
    return true;
  };
}

export function conformsBoth<U, T1 extends U, T2 extends T1>(predicate1: Predicate<U, T1>, predicate2: Predicate<T1, T2>) {
  return function (u: U): u is T1 & T2 {
    return predicate1(u) && predicate2(u);
  };
}

export function conformsEither<U, T1 extends U, T2 extends U>(predicate1: Predicate<U, T1>, predicate2: Predicate<U, T2>) {
  return function (u: U): u is T1 | T2 {
    return predicate1(u) || predicate2(u);
  };
}

export function filter<U, T extends U>(predicate: Predicate<U, T>) {
  return function (u: U[]): T[] {
    return u.filter(predicate);
  };
}

// deno-lint-ignore no-explicit-any
export function conformsAny<U, T extends Predicate<U, any>[]>(...predicates: T) {
  return function (u: U): u is T extends Predicate<U, infer P>[] ? P : never {
    return predicates.some((predicate) => predicate(u));
  };
}

// deno-lint-ignore no-explicit-any
export function conformsAll<U>(): Predicate<U, U>;
export function conformsAll<U, T1 extends U>(predicate: Predicate<U, T1>): Predicate<U, T1>;
export function conformsAll<U, T1 extends U, T2 extends T1>(predicate_0: Predicate<U, T1>, predicate_1: Predicate<T1, T2>): Predicate<U, T2>;
export function conformsAll<U, T1 extends U, T2 extends T1, T3 extends T2>(
  predicate_0: Predicate<U, T1>,
  predicate_1: Predicate<T1, T2>,
  predicate_2: Predicate<T2, T3>,
): Predicate<U, T3>;
export function conformsAll<U, T1 extends U, T2 extends T1, T3 extends T2, T4 extends T3>(
  predicate_0: Predicate<U, T1>,
  predicate_1: Predicate<T1, T2>,
  predicate_2: Predicate<T2, T3>,
  predicate_3: Predicate<T3, T4>,
): Predicate<U, T4>;
export function conformsAll<U, T1 extends U, T2 extends T1, T3 extends T2, T4 extends T3, T5 extends T4>(
  predicate_0: Predicate<U, T1>,
  predicate_1: Predicate<T1, T2>,
  predicate_2: Predicate<T2, T3>,
  predicate_3: Predicate<T3, T4>,
  predicate_4: Predicate<T4, T5>,
): Predicate<U, T5>;
export function conformsAll<U, T1 extends U, T2 extends T1, T3 extends T2, T4 extends T3, T5 extends T4, T6 extends T5>(
  predicate_0: Predicate<U, T1>,
  predicate_1: Predicate<T1, T2>,
  predicate_2: Predicate<T2, T3>,
  predicate_3: Predicate<T3, T4>,
  predicate_4: Predicate<T4, T5>,
  predicate_5: Predicate<T5, T6>,
): Predicate<U, T6>;
export function conformsAll<U, T1 extends U, T2 extends T1, T3 extends T2, T4 extends T3, T5 extends T4, T6 extends T5, T7 extends T6>(
  predicate_0: Predicate<U, T1>,
  predicate_1: Predicate<T1, T2>,
  predicate_2: Predicate<T2, T3>,
  predicate_3: Predicate<T3, T4>,
  predicate_4: Predicate<T4, T5>,
  predicate_5: Predicate<T5, T6>,
  predicate_6: Predicate<T6, T7>,
): Predicate<U, T7>;
export function conformsAll<U, T1 extends U, T2 extends T1, T3 extends T2, T4 extends T3, T5 extends T4, T6 extends T5, T7 extends T6, T8 extends T7>(
  predicate_0: Predicate<U, T1>,
  predicate_1: Predicate<T1, T2>,
  predicate_2: Predicate<T2, T3>,
  predicate_3: Predicate<T3, T4>,
  predicate_4: Predicate<T4, T5>,
  predicate_5: Predicate<T5, T6>,
  predicate_6: Predicate<T6, T7>,
  predicate_7: Predicate<T7, T8>,
): Predicate<U, T8>;
export function conformsAll<
  U,
  T1 extends U,
  T2 extends T1,
  T3 extends T2,
  T4 extends T3,
  T5 extends T4,
  T6 extends T5,
  T7 extends T6,
  T8 extends T7,
  T9 extends T8,
>(
  predicate_0: Predicate<U, T1>,
  predicate_1: Predicate<T1, T2>,
  predicate_2: Predicate<T2, T3>,
  predicate_3: Predicate<T3, T4>,
  predicate_4: Predicate<T4, T5>,
  predicate_5: Predicate<T5, T6>,
  predicate_6: Predicate<T6, T7>,
  predicate_7: Predicate<T7, T8>,
  predicate_8: Predicate<T8, T9>,
): Predicate<U, T9>;

export function conformsAll<U, T extends Predicate<U, any>[]>(...predicates: T) {
  return function (u: U) {
    return predicates.every((predicate) => predicate(u));
  };
}
