import { FileStorage } from "window/Storage/FileStorage.ts";
import { Storer } from "window/Storage/Manager.ts";
import { Optional } from "common/serialisation/optional.ts";
import { postponable } from "common/postponable.ts";
import { syncThen } from "common/async.ts";

export type FileData = File | {
  name: string;
  file: Promise<File>;
};

type NameOf<F extends FileData | undefined> = F extends undefined ? undefined : F extends File ? string : Promise<string>;
type FileOf<F extends FileData | undefined> = F extends undefined ? undefined : F extends File ? File : Promise<File>;

export class FileStorer extends Storer<FileData> {
  readonly #files: FileStorage;

  constructor(files: FileStorage) {
    super();
    this.#files = files;
  }

  override load(key: string): Optional<FileData> {
    const name = localStorage.getItem(key);
    if (name === null) return new Optional(false);
    return new Optional<FileData>(true, { name, file: this.#files.get(key) });
  }

  override save(key: string, value: Optional<FileData>, prevValue: Optional<FileData>): boolean {
    const prev = prevValue.getValueOr(undefined);
    const curr = value.getValueOr(undefined);
    if (prev?.name === curr?.name) return false;
    this.#save(key, FileStorer.fileOf(curr));
    const name = FileStorer.nameOf(curr);
    if (name === undefined) {
      localStorage.removeItem(key);
    } else {
      syncThen(name, (name) => localStorage.setItem(key, name));
    }
    return true;
  }

  static nameOf<F extends FileData | undefined>(value: F): NameOf<F> {
    if (value === undefined) return undefined as NameOf<F>;
    if (value instanceof File) return value.name as NameOf<F>;
    return value.file.then((file) => file.name) as NameOf<F>;
  }

  static fileOf<F extends FileData | undefined>(value: F): FileOf<F> {
    if (value === undefined) return undefined as FileOf<F>;
    if (value instanceof File) return value as File as FileOf<F>;
    return value.file as FileOf<F>;
  }

  #save = postponable((key: string, value: File | Promise<File> | undefined) => this.#saveOp(key, value));
  async #saveOp(key: string, value: File | Promise<File> | undefined) {
    if (value === undefined) {
      await this.#files.delete(key);
    } else {
      await this.#files.set(key, await value);
    }
  }
}
