import { Field } from "window/components/Field.tsx";

export class DownloadField extends Field<boolean, true> {
  readonly #button: HTMLButtonElement;
  readonly #state: { disabled: boolean; downloaded: boolean };

  constructor({ label = "", buttonText = "Download", disabled = false, downloaded = false, onclick }: Partial<{
    label: string;
    buttonText: string;
    disabled: boolean;
    downloaded: boolean;
    onclick: (event: MouseEvent) => unknown;
  }> = {}) {
    const button = <button>{buttonText}</button> as HTMLButtonElement;
    const state = { disabled, downloaded };
    super({
      children: button,
      getValue: () => state.downloaded,
      label,
      process: () => state.disabled || state.downloaded ? { valid: true } : { invalid: ["has not been downloaded"] },
    });
    this.#button = button;
    this.#state = state;
    this.disabled = disabled;
    this.style.display = "inline-flex";
    this.style.alignItems = "center";
    this.style.gap = "0.5rem";
    this.#button.addEventListener("click", (event) => {
      this.validate({ touched: true });
      onclick?.(event);
    });
  }

  get disabled() {
    return this.#state.disabled;
  }

  set disabled(value: boolean) {
    this.#state.disabled = value;
    this.#button.disabled = value;
    this.validate();
  }

  get downloaded() {
    return this.#state.downloaded;
  }

  set downloaded(value: boolean) {
    this.#state.downloaded = value;
    this.validate();
  }

  override validate({ touched = false }: { force?: boolean; touched?: boolean } = {}) {
    super.validate({ touched });
  }
}
