export type ProcessResult<T> =
  | { valid: T }
  | { invalid: readonly string[] };

export type ValidationEvents = {
  "custom-validate": readonly string[];
};

export function processResultToErrors(result: ProcessResult<unknown>): readonly string[] {
  if ("valid" in result) return [];
  return result.invalid;
}

export function prefixValidationErrors(identifier: string, errors: readonly string[]): readonly string[] {
  return errors.map((error) => `${identifier}: ${error}`);
}
