import { isPromiseLike } from "common/typeNarrow.ts";

/**
 * An event listener adder
 * @param thing What the event occurs to
 * @param does The event that occurs
 * @param then What to do when the event occurs
 * @returns object containing method to stop listening
 */
export function when(thing: EventTarget, does: string, then: EventListenerOrEventListenerObject, options?: AddEventListenerOptions) {
  thing.addEventListener(does, then, options);
  return {
    stop: () => {
      thing.removeEventListener(does, then, options);
    },
  };
}

export function once(thing: EventTarget, does: string, then: EventListenerOrEventListenerObject, options?: AddEventListenerOptions) {
  thing.addEventListener(does, then, { ...options, once: true });
  return {
    abort: () => {
      thing.removeEventListener(does, then, options?.capture);
    },
  };
}

export function sleep(seconds: number, abortSignal?: AbortSignal) {
  if (seconds === Infinity) {
    return new Promise<boolean>((go) => {
      if (abortSignal !== undefined) {
        if (abortSignal.aborted) {
          go(false);
          return;
        }
        once(abortSignal, "abort", () => {
          go(false);
        });
      }
    });
  }
  return new Promise<boolean>((go) => {
    if (abortSignal === undefined) {
      setTimeout(() => go(true), seconds * 1000);
    } else {
      if (abortSignal.aborted) {
        go(false);
        return;
      }
      const timer = setTimeout(() => {
        stopSleeping.abort();
        go(true);
      }, seconds * 1000);
      const stopSleeping = once(abortSignal, "abort", () => {
        clearTimeout(timer);
        go(false);
      });
    }
  });
}

type SemaphoreEntry = {
  exit(): void;
};

export class Semaphore {
  #finalEntry?: SemaphoreEntry;

  /**
   * call enter when you enter a zone of mutual exclusion
   * @returns a promise of permission to enter and the ability to exit
   */
  private enter() {
    return new Promise<SemaphoreEntry>((go) => {
      const newEntry = {
        exit: () => {
          if (this.#finalEntry === newEntry) {
            this.#finalEntry = undefined;
          }
        },
      };
      if (this.#finalEntry === undefined) {
        // no previous entry. Immediately trigger entry.
        this.#finalEntry = newEntry;
        go(this.#finalEntry);
      } else {
        // Previous entry exists. We must update its exit to trigger the new entry.
        const previousEntry = this.#finalEntry;
        this.#finalEntry = newEntry;
        previousEntry.exit = () => {
          go(newEntry);
        };
      }
    });
  }

  get locked() {
    return this.#finalEntry !== undefined;
  }

  /**
   * Enters the semaphore before calling the callback and exits once done and optionally delayed, or once an exception is thrown.
   * @param callback the callback to call once entered
   * @param delayExit don't exit until this promise settles
   * @returns promise that resolves once entered, callback is run, delayExit is settled, and exited.
   * If delayExit is given, returns an array of the callback result and delayExit result, otherwise returns just the callback result
   */
  async call<T>(callback: () => Promise<T> | T): Promise<T>;
  async call<T, X>(callback: () => Promise<T> | T, delayExit: Promise<X>): Promise<[T, Promise<X>]>;
  async call<T, X = void>(callback: () => Promise<T> | T, delayExit?: Promise<X>) {
    const entry = await this.enter();
    if (delayExit === undefined) {
      return (async () => await callback())().finally(() => entry.exit());
    } else {
      return (async () => await callback())().then(
        (result) =>
          [
            result,
            delayExit.finally(() => entry.exit()),
          ] as [T, Promise<X>],
        (e) => {
          entry.exit();
          throw e;
        },
      );
    }
  }
}

export function abortable<T>(promise: Promise<T>, signal: AbortSignal) {
  return new Promise<T>((go, no) => {
    const cancel = () => no(signal.reason);
    const { abort } = once(signal, "abort", cancel);
    promise.then(go, no).finally(abort);
    if (signal.aborted) {
      abort();
      cancel();
    }
  });
}

export function waitForAbort(signal: AbortSignal, stop?: AbortSignal) {
  stop?.throwIfAborted();
  if (signal.aborted) {
    return Promise.resolve();
  }

  return new Promise<void>((resolve, reject) => {
    signal.addEventListener("abort", () => resolve(), { once: true, signal: stop });
    stop?.addEventListener("abort", () => reject(stop.reason), { once: true, signal });
  });
}

type Fulfilled<T> = T extends PromiseLike<infer X> ? Awaited<X> : T;

/**
 * If `value` is `PromiseLike`, returns `value.then(onfulfilled, onrejected)`.
 * Otherwise returns `onfulfilled(value)`, or `value` if `onfulfilled` is `null` or `undefined`.
 */
export function syncThen<T, E = never>(value: T, onfulfilled?: null, onrejected?: ((e: unknown) => E) | null): T;
export function syncThen<E = never>(
  value: PromiseLike<never>,
  onfulfilled?: ((t: unknown) => unknown) | null,
  onrejected?: ((e: unknown) => E) | null,
): PromiseLike<E>;
export function syncThen<T, R, E = never>(
  value: T,
  onfulfilled: (t: Fulfilled<T>) => R,
  onrejected?: ((e: unknown) => E) | null,
): T extends PromiseLike<unknown> ? PromiseLike<Awaited<NoInfer<R>> | Awaited<NoInfer<E>>>
  : NoInfer<R>;
export function syncThen<T, R = Fulfilled<T>, E = never>(
  value: T,
  onfulfilled?: ((t: Fulfilled<T>) => R) | null,
  onrejected?: ((e: unknown) => E) | null,
) {
  type Ret = T extends PromiseLike<unknown> ? PromiseLike<Awaited<R> | Awaited<E>> : R;
  if (isPromiseLike(value)) return (value as PromiseLike<Fulfilled<T>>).then(onfulfilled, onrejected) as Ret;
  return (onfulfilled === undefined || onfulfilled === null ? value : onfulfilled(value as Fulfilled<T>)) as Ret;
}
