import { EventHandlers } from "web/TypedEventHTMLElement.tsx";
import { Field, FieldEvents } from "window/components/Field.tsx";
import { ProcessResult } from "window/validation.ts";
import { InputType } from "jsx/props.ts";

export class InputField<Value = string> extends Field<string, Value> {
  readonly input: HTMLInputElement;

  constructor({
    classList = [],
    disabled = false,
    label,
    max,
    min,
    onchange = null,
    oninput = null,
    process,
    step,
    type = "text",
    value = "",
    ...events
  }:
    & Partial<EventHandlers<FieldEvents<Value>>>
    & {
      classList?: readonly string[] | DOMTokenList;
      disabled?: boolean;
      label: string;
      max?: string;
      min?: string;
      process?: (value: string) => ProcessResult<Value>;
      step?: string;
      type?: InputType;
      value?: string;
    }) {
    const input = (
      <input
        disabled={disabled}
        max={max}
        min={min}
        step={step}
        type={type}
        value={value}
      />
    ) as HTMLInputElement;
    input.classList.add(...classList);
    if (onchange !== null) input.addEventListener("change", onchange);
    if (oninput !== null) input.addEventListener("input", oninput);

    super({
      children: input,
      getValue: () => input.value,
      label,
      process,
      ...events,
    });

    this.input = input;
  }
}
