import { ErrorIndicator } from "window/components/ErrorIndicator.tsx";
import { TabPanel } from "window/components/TabPanel.tsx";
import { addTypedEvents, EventHandlers } from "web/TypedEventHTMLElement.tsx";
import { ValidationEvents } from "window/validation.ts";

const TypedHTMLLabelElement = addTypedEvents(HTMLLabelElement);

type TabItemEvents = ValidationEvents & {
  "tab-select": TabPanel;
};

export class TabItem extends TypedHTMLLabelElement<TabItemEvents> {
  readonly #input: HTMLInputElement;

  constructor({ tab, name, ...events }: { tab: TabPanel; name: string } & EventHandlers<TabItemEvents>) {
    super(events);
    const input = (
      <input
        name={name}
        style={{
          position: "absolute",
          inlineSize: "1px",
          blockSize: "1px",
          opacity: "0",
          pointerEvents: "none",
        }}
        type="radio"
        value={tab.label}
      />
    ) as HTMLInputElement;
    const error = <ErrorIndicator /> as ErrorIndicator;

    this.#input = input;
    this.classList.add("tab-menu-tab");
    this.replaceChildren(input, tab.label, error);

    input.onchange = () => this.emit("tab-select", tab);
    tab.addEventListener("custom-validate", ({ detail: errors }) => error.errors = errors);
  }

  set selected(value: boolean) {
    this.#input.checked = value;
  }
}
