import { TypedEventHTMLElement } from "web/TypedEventHTMLElement.tsx";
import { ValidationEvents } from "window/validation.ts";
import { validateDescendants } from "window/components/validateDescendants.tsx";

export class TabPanel extends TypedEventHTMLElement<ValidationEvents> {
  readonly #childErrors = new Map<EventTarget, readonly string[]>();
  readonly label: string;
  constructor({ label }: { label: string }) {
    super();
    this.label = label;

    this.addEventListener("custom-validate", (event) => {
      if (event.target === this) return;
      if (event.target === null) return;
      event.stopImmediatePropagation();
      if (event.detail.length === 0) {
        this.#childErrors.delete(event.target);
      } else {
        this.#childErrors.set(event.target, event.detail);
      }
      this.emit("custom-validate", [...this.#childErrors.values()].flat(), { bubbles: true });
    });
  }

  hasErrors({ except = new Set<EventTarget>() }: { except?: ReadonlySet<EventTarget> } = {}) {
    return [...this.#childErrors].some(([source, errors]) => errors.length > 0 && !except.has(source));
  }

  validate(options: { force?: boolean; touched?: boolean } = { force: true }) {
    validateDescendants(this, options);
  }
}
