import { getContentBoxSize } from "window/components/layout.ts";
import { ElementChildrenAttribute } from "jsx/props.ts";

export class PDFPages extends HTMLElement {
  readonly #getPageDimensions: (() => { width: number; height: number } | undefined) | undefined;
  #pageDimensions: { width: number; height: number } | undefined;

  constructor({ children = [], getPageDimensions }: Partial<ElementChildrenAttribute> & {
    getPageDimensions?: () => { width: number; height: number } | undefined;
  } = {}) {
    super();
    this.#getPageDimensions = getPageDimensions;
    this.style.boxSizing = "border-box";
    this.style.display = "grid";
    this.style.gridTemplateColumns = "repeat(2, minmax(0, 1fr))";
    this.style.gridTemplateRows = "minmax(0, 1fr)";
    this.style.gap = "0.5rem";
    this.style.padding = "0.5rem";
    this.style.width = "100%";
    this.style.height = "100%";
    this.style.minWidth = "0";
    this.style.minHeight = "0";
    this.replaceChildren(...(Array.isArray(children) ? children : [children]));
    this.addEventListener("pdf-page-change", (event) => {
      if (!(event instanceof CustomEvent)) return;
      this.#pageDimensions = event.detail;
      this.updateLayout();
    });
    new ResizeObserver(() => this.updateLayout()).observe(this);
  }

  updateLayout() {
    const dimensions = this.#getPageDimensions?.() ?? this.#pageDimensions;
    if (dimensions === undefined) return;
    const { width, height } = dimensions;
    const available = getContentBoxSize(this);
    if (available.width <= 0 || available.height <= 0) return;

    const sideBySideScale = Math.min(available.width / 2 / width, available.height / height);
    const stackedScale = Math.min(available.width / width, available.height / 2 / height);
    const stacked = stackedScale > sideBySideScale;
    this.style.gridTemplateColumns = stacked ? "minmax(0, 1fr)" : "repeat(2, minmax(0, 1fr))";
    this.style.gridTemplateRows = stacked ? "repeat(2, minmax(0, 1fr))" : "minmax(0, 1fr)";
  }
}
