import { Manager } from "window/Storage/Manager.ts";
import { JSONStorer } from "window/Storage/JSONStorer.ts";
import { BooleanStorer } from "window/Storage/BooleanStorer.ts";
import { StringStorer } from "window/Storage/StringStorer.ts";
import { isConformingArray, isType } from "common/typeNarrow.ts";

const codesStore = {
  codes: {
    first: new StringStorer(),
    last: new StringStorer(),
    format: new StringStorer(),
    csvDownloaded: new BooleanStorer(),
    codes: new JSONStorer(isConformingArray(isType("string")), (v) => v, (v) => v),
  },
};

export class CodesManager extends Manager<typeof codesStore> {
  static readonly instance = new CodesManager();

  private constructor() {
    super(codesStore);
  }

  setSettings({ first, last, format }: { first: string; last: string; format: string }) {
    this.set("codes.first", first);
    this.set("codes.last", last);
    this.set("codes.format", format);
  }

  update({ format, min, max }: { format: string; min: number; max: number }) {
    this.batch(() => {
      this.set("codes.codes", [...this.generate(format, min, max)]);
      this.set("codes.csvDownloaded", false);
    });
  }

  clear() {
    this.batch(() => {
      this.set("codes.csvDownloaded", false);
      this.set("codes.codes", []);
    });
  }

  private *generate(format: string, min: number, max: number) {
    if (max < min) {
      throw new Error("Maximum cannot be less than minimum");
    }

    const matches = format.match(/(?:\\.)|i|x|[^\\ix]*/g) ?? [];
    const iMatch = matches.filter((value) => value === "i");

    if (max >= 10 ** iMatch.length) {
      throw new Error("Cannot fit all codes in the provided format");
    }

    // Build each string in reverse
    matches.reverse();
    for (let i = min; i <= max; ++i) {
      const iStr = String(i);
      let idx = 0;
      const ret = matches.map((match) => {
        if (match === "i") {
          return iStr.at(-++idx) ?? "0";
        } else if (match === "x") {
          return String(Math.floor(Math.random() * 10));
        } else if (match.startsWith("\\")) {
          return match[1];
        } else {
          return match;
        }
      }).reverse().join("");
      yield ret;
    }
  }
}
