type CustomisedBuiltinJSXElement<T extends keyof HTMLElementTagNameMap> = { element: CustomElementConstructor<HTMLElementTagNameMap[T]>; extends: T };
type AutonomousCustomJSXElement = { element: CustomElementConstructor };

export type CustomJSXElements = {
  [K in `${string}-${string}`]: AutonomousCustomJSXElement | CustomisedBuiltinJSXElement<keyof HTMLElementTagNameMap>;
};

let created = false;

export function customJSXElementsFactory<T extends CustomJSXElements>(
  customJSXElements: T,
): keyof T extends `${string}-${string}` ? T : "All keys must have a hyphen" {
  if (created) throw new Error("Cannot create customJSXElements more than once");
  created = true;
  for (const customTag in customJSXElements) {
    const custom = customJSXElements[customTag as keyof typeof customJSXElements] as CustomJSXElements[keyof CustomJSXElements];
    if ("extends" in custom) {
      customElements.define(customTag, custom["element"], { extends: custom["extends"] });
    } else {
      customElements.define(customTag, custom["element"]);
    }
  }
  return customJSXElements as keyof T extends `${string}-${string}` ? T : never;
}

export type CustomElementPrototype<Attributes extends boolean = boolean, Form extends boolean = boolean> =
  & {
    connectedCallback?: () => void;
    disconnectedCallback?: () => void;
    adoptedCallback?: () => void;
  }
  & (Attributes extends true ? {
      attributeChangedCallback: (name: string, oldValue: string, newValue: string) => void;
    }
    : {
      attributeChangedCallback?: undefined;
    })
  & (Form extends true ? {
      formAssociatedCallback?: () => void;
      formResetCallback?: () => void;
      formDisabledCallback?: () => void;
      formStateRestoreCallback?: () => void;
    }
    : {
      formAssociatedCallback?: undefined;
      formResetCallback?: undefined;
      formDisabledCallback?: undefined;
      formStateRestoreCallback?: undefined;
    });

export type CustomElementConstructor<T extends HTMLElementTagNameMap[keyof HTMLElementTagNameMap] = HTMLElement> =
  & {
    readonly disabledFeatures?: string[];
  }
  & ({
    readonly observedAttributes?: undefined;
    readonly formAssociated?: undefined | false;
    new (props: any): T & CustomElementPrototype<false, false>;
  } | {
    readonly observedAttributes: string[];
    readonly formAssociated?: undefined | false;
    new (props: any): T & CustomElementPrototype<true, false>;
  } | {
    readonly observedAttributes?: undefined;
    readonly formAssociated: true;
    new (props: any): T & CustomElementPrototype<false, true>;
  } | {
    readonly observedAttributes: string[];
    readonly formAssociated: true;
    new (props: any): T & CustomElementPrototype<true, true>;
  });
