import { CodesManager } from "window/Pages/Codes/CodesManager.ts";
import { InputManager } from "window/Pages/Input/InputManager.ts";
import { processFraction } from "window/components/Field.tsx";
import { FileField, InputField, PDFFile, PDFFileWithOverlay, PDFPages, Section } from "jsx/custom";
import { TabPanel } from "window/components/TabPanel.tsx";
import { getDocument, PDFDocumentProxy } from "pdfjs-dist";
import { syncThen } from "common/async.ts";
import { FileStorer } from "window/Storage/FileStorer.ts";

export class InputPage extends TabPanel {
  #numericInputValue(value: number) {
    return Number.isFinite(value) ? `${value}` : "";
  }

  readonly #frontRenderer = <PDFFile /> as PDFFile;
  readonly #backRenderer = <PDFFileWithOverlay /> as PDFFileWithOverlay;
  readonly #pagesFileField = (
    <FileField
      accept="application/pdf,.pdf"
      label="PDF File"
      onfile-clear={async () => {
        InputManager.instance.remove("input.pages.file");
        await this.showPdfDocument(undefined);
      }}
      onfile-select={({ detail: file }) => this.#loadPagesFile(file, { resetFile: true })}
    />
  ) as FileField;
  readonly #textField = (
    <InputField
      label="Code"
      oninput={() => {
        this.#codeIndex = undefined;
        this.#setCode(this.#textField.input.value);
      }}
      value={InputManager.instance.get("input.text.value").getValueOr("")}
    />
  ) as InputField<string>;

  readonly #textXField = (
    <InputField
      classList={["fraction-input"]}
      label="x"
      oninput={() => this.#updateTextPosition()}
      process={processFraction}
      step="any"
      type="number"
      value={this.#numericInputValue(InputManager.instance.get("input.text.x").getValueOr(NaN))}
    />
  ) as InputField<number>;
  readonly #textYField = (
    <InputField
      classList={["fraction-input"]}
      label="y"
      oninput={() => this.#updateTextPosition()}
      process={processFraction}
      step="any"
      type="number"
      value={this.#numericInputValue(InputManager.instance.get("input.text.y").getValueOr(NaN))}
    />
  ) as InputField<number>;
  readonly #textHeightField = (
    <InputField
      classList={["fraction-input"]}
      label="Height"
      oninput={() => {
        const height = this.#textHeightField.input.valueAsNumber;
        InputManager.instance.set("input.text.height", height);
        this.#backRenderer.textHeight = height;
        this.#backRenderer.renderLoadedPage();
      }}
      process={processFraction}
      step="any"
      type="number"
      value={this.#numericInputValue(InputManager.instance.get("input.text.height").getValueOr(NaN))}
    />
  ) as InputField<number>;
  readonly #markerColorInput = (
    <input
      type="color"
      value={InputManager.instance.get("input.marker.color").getValueOr("#FF0000")}
      oninput={() => {
        InputManager.instance.set("input.marker.color", this.#markerColorInput.value);
        this.#backRenderer.markerColor = this.#markerColorInput.value;
        this.#backRenderer.renderLoadedPage();
      }}
    />
  ) as HTMLInputElement;
  readonly #markerVisibleInput = (
    <input
      type="checkbox"
      checked={InputManager.instance.get("input.marker.visible").getValueOr(true)}
      onchange={() => {
        InputManager.instance.set("input.marker.visible", this.#markerVisibleInput.checked);
        this.#backRenderer.markerVisible = this.#markerVisibleInput.checked;
        this.#backRenderer.renderLoadedPage();
      }}
    />
  ) as HTMLInputElement;
  readonly #previousCodeButton = (
    <button onclick={() => this.#previousCode()}>
      prev code
    </button>
  ) as HTMLButtonElement;
  readonly #nextCodeButton = (
    <button onclick={() => this.#nextCode()}>
      next code
    </button>
  ) as HTMLButtonElement;

  readonly #fontFileField = (
    <FileField
      accept=".ttf,.otf,.woff,.woff2"
      label="Font File"
      onfile-clear={() => InputManager.instance.remove("input.font.file")}
      onfile-select={(event) => this.#loadFontFile(event.detail)}
    />
  ) as FileField;
  readonly #pageOptions = (
    <Section
      collapsed={InputManager.instance.get("input.fieldset.page-options.collapsed").getValueOr(false)}
      label="Pages"
      oncollapsechange={(event) => InputManager.instance.set("input.fieldset.page-options.collapsed", event.detail.collapsed)}
    >
      {this.#pagesFileField}
    </Section>
  ) as Section;
  readonly #textOptions = (
    <Section
      classList={["option-grid"]}
      collapsed={InputManager.instance.get("input.fieldset.text-options.collapsed").getValueOr(false)}
      label="Text"
      oncollapsechange={(event) => InputManager.instance.set("input.fieldset.text-options.collapsed", event.detail.collapsed)}
    >
      <Section
        collapsed={InputManager.instance.get("input.fieldset.text-code-options.collapsed").getValueOr(false)}
        label="Test"
        oncollapsechange={(event) => InputManager.instance.set("input.fieldset.text-code-options.collapsed", event.detail.collapsed)}
      >
        {this.#textField}
        <div style={{ gridColumn: "1/-1" }}>
          {this.#previousCodeButton}
          {this.#nextCodeButton}
        </div>
        <Section
          collapsed={InputManager.instance.get("input.fieldset.text-marker-options.collapsed").getValueOr(false)}
          label="Marker"
          oncollapsechange={(event) => InputManager.instance.set("input.fieldset.text-marker-options.collapsed", event.detail.collapsed)}
        >
          <label>
            <span>Colour</span>
            {this.#markerColorInput}
          </label>
          <label>
            <span>Visible</span>
            {this.#markerVisibleInput}
          </label>
        </Section>
      </Section>
      <Section
        collapsed={InputManager.instance.get("input.fieldset.text-position-options.collapsed").getValueOr(false)}
        label="Position"
        oncollapsechange={(event) => InputManager.instance.set("input.fieldset.text-position-options.collapsed", event.detail.collapsed)}
      >
        {this.#textXField}
        {this.#textYField}
      </Section>
      <Section
        collapsed={InputManager.instance.get("input.fieldset.text-font-options.collapsed").getValueOr(false)}
        label="Font"
        oncollapsechange={(event) => InputManager.instance.set("input.fieldset.text-font-options.collapsed", event.detail.collapsed)}
      >
        {this.#fontFileField}
        {this.#textHeightField}
      </Section>
    </Section>
  ) as Section;
  readonly #pages = (
    <PDFPages>
      {this.#frontRenderer}
      {this.#backRenderer}
    </PDFPages>
  ) as PDFPages;

  constructor() {
    super({ label: "Input" });
    this.style.minWidth = "0";
    this.style.minHeight = "0";
    this.style.display = "grid";
    this.style.gridTemplateRows = "auto minmax(0, 1fr)";
    this.style.gap = "0.5rem";

    this.replaceChildren(
      <div className="option-grid" style={{ minWidth: "0", minInlineSize: "0" }}>
        {this.#pageOptions}
        {this.#textOptions}
      </div>,
      this.#pages,
    );

    this.#backRenderer.canvas.addEventListener("click", (event) => {
      const rect = this.#backRenderer.canvas.getBoundingClientRect();
      this.#textXField.input.value = ((event.clientX - rect.left) / rect.width).toFixed(4);
      this.#textYField.input.value = (1 - (event.clientY - rect.top) / rect.height).toFixed(4);
      this.#updateTextPosition();
    });
    this.#backRenderer.text = InputManager.instance.get("input.text.value").getValueOr("");
    this.#backRenderer.textPosition = {
      x: InputManager.instance.get("input.text.x").getValueOr(NaN),
      y: InputManager.instance.get("input.text.y").getValueOr(NaN),
    };
    this.#backRenderer.textHeight = InputManager.instance.get("input.text.height").getValueOr(NaN);
    this.#backRenderer.markerColor = InputManager.instance.get("input.marker.color").getValueOr("#FF0000");
    this.#backRenderer.markerVisible = InputManager.instance.get("input.marker.visible").getValueOr(true);
    this.#backRenderer.renderLoadedPage();
    const codeIndex = CodesManager.instance.get("codes.codes").getValueOr(new Array<string>()).indexOf(
      InputManager.instance.get("input.text.value").getValueOr(""),
    );
    this.#codeIndex = codeIndex === -1 ? undefined : codeIndex;

    this.#restoreStoredFiles();
  }

  async #restoreStoredFiles() {
    const tasks = new Array<PromiseLike<void>>();

    const storedPagesFile = InputManager.instance.get("input.pages.file").getValueOr(undefined);
    if (storedPagesFile !== undefined) {
      tasks.push(syncThen(FileStorer.fileOf(storedPagesFile), (file) => this.#loadPagesFile(file)));
    }

    const storedFontFile = InputManager.instance.get("input.font.file").getValueOr(undefined);
    if (storedFontFile !== undefined) {
      tasks.push(syncThen(FileStorer.fileOf(storedFontFile), (file) => this.#loadFontFile(file, { persist: false }).catch((error) => console.error(error))));
    }

    await Promise.all(tasks);
  }

  #updateTextPosition() {
    const position = {
      x: this.#textXField.input.valueAsNumber,
      y: this.#textYField.input.valueAsNumber,
    };
    InputManager.instance.batch(() => {
      InputManager.instance.set("input.text.x", position.x);
      InputManager.instance.set("input.text.y", position.y);
    });
    this.#backRenderer.textPosition = position;
    this.#backRenderer.renderLoadedPage();
  }

  async #loadPagesFile(file: File, { resetFile = false }: { resetFile?: boolean } = {}) {
    if (resetFile) InputManager.instance.set("input.pages.file", file);
    this.#pagesFileField.setFile(file);

    try {
      const pdf = await getDocument({ data: new Uint8Array(await file.arrayBuffer()) }).promise;
      if (pdf.numPages !== 2) {
        this.#pagesFileField.setValidationError("must have 2 pages");
        throw new Error(`Expected a PDF with 2 pages, got ${pdf.numPages}`);
      }
      this.#pagesFileField.setValidationError(undefined);
      await this.showPdfDocument(pdf);
    } catch (error) {
      await this.showPdfDocument(undefined);
      if (!this.#pagesFileField.hasError()) this.#pagesFileField.setValidationError("must be a valid PDF");
      console.error(error);
      return undefined;
    }
  }

  #pdfDocument: PDFDocumentProxy | undefined;
  private async showPdfDocument(pdfDocument: PDFDocumentProxy | undefined) {
    this.#pdfDocument = pdfDocument;
    this.#frontRenderer.page = undefined;
    this.#backRenderer.page = undefined;

    await Promise.all([
      this.#pdfDocument?.getPage(1).then((page) => this.#frontRenderer.page = page),
      this.#pdfDocument?.getPage(2).then((page) => this.#backRenderer.page = page),
    ]);
  }

  async #loadFontFile(file: File, { persist = true }: { persist?: boolean } = {}) {
    this.#fontFileField.setFile(file);
    if (persist) InputManager.instance.set("input.font.file", file);
    try {
      const font = new FontFace(`voucher-code-${crypto.randomUUID()}`, await file.arrayBuffer());
      document.fonts.add(await font.load());
      this.#backRenderer.fontFamily = font.family;
      this.#backRenderer.renderLoadedPage();
      this.#fontFileField.setValidationError(undefined);
    } catch (error) {
      this.#fontFileField.setValidationError("must be a valid font");
      console.error(error);
    }
  }

  #setCode(code: string) {
    InputManager.instance.set("input.text.value", code);
    this.#textField.input.value = code;
    this.#backRenderer.text = code;
    this.#backRenderer.renderLoadedPage();
  }

  #codeIndex: number | undefined;
  #previousCode() {
    const codes = CodesManager.instance.get("codes.codes").getValueOr([]);
    if (codes.length === 0) return;
    this.#codeIndex = this.#codeIndex === undefined ? codes.length - 1 : (this.#codeIndex - 1 + codes.length) % codes.length;
    this.#setCode(codes[this.#codeIndex]);
  }

  #nextCode() {
    const codes = CodesManager.instance.get("codes.codes").getValueOr([]);
    if (codes.length === 0) return;
    this.#codeIndex = this.#codeIndex === undefined ? 0 : (this.#codeIndex + 1) % codes.length;
    this.#setCode(codes[this.#codeIndex]);
  }
}
