import { Predicate } from "common/typeNarrow.ts";
import { Storer } from "window/Storage/Manager.ts";
import { Optional } from "common/serialisation/optional.ts";

export class JSONStorer<Raw, T> extends Storer<T> {
  constructor(
    private readonly predicate: Predicate<unknown, Raw>,
    private readonly deserialise: (value: Raw) => T,
    private readonly serialise: (value: T) => Raw,
  ) {
    super();
  }

  override load(key: string): Optional<T> {
    const value = localStorage.getItem(key);
    return value === null ? new Optional(false) : this.parse(value);
  }

  override save(key: string, value: Optional<T>, prevValue: Optional<T>): boolean {
    const prev = this.stringify(prevValue);
    const curr = this.stringify(value);
    if (prev.getValueOr(undefined) === curr.getValueOr(undefined)) return false;

    if (!curr.value.hasValue) {
      localStorage.removeItem(key);
    } else {
      localStorage.setItem(key, curr.value.value);
    }
    return true;
  }

  parse(value: string): Optional<T> {
    try {
      const parsed = JSON.parse(value);
      return this.predicate(parsed) ? new Optional(true, this.deserialise(parsed)) : new Optional(false);
    } catch {
      return new Optional(false);
    }
  }

  stringify(value: Optional<T>): Optional<string> {
    if (value.value.hasValue) {
      return new Optional(true, JSON.stringify(this.serialise(value.value.value)));
    }
    return new Optional(false);
  }
}
