import { SerialisableBoolean } from "common/serialisation/basic.ts";
import { RemoveOneStaticSerialisable, Serialisable, SerialisableConstructor } from "common/serialisation.ts";
import { SerialisableThroughFunction } from "common/serialisation/instance.ts";
import { SerialisableTuple } from "common/serialisation/tuple.ts";

type OptionalData<T> = {
  hasValue: true;
  value: T;
} | {
  hasValue: false;
};

export class Optional<T> {
  #data: OptionalData<T>;
  constructor(optional: Optional<T>);
  constructor(hasValue: true, value: T);
  constructor(hasValue: false);
  constructor(hasValue: boolean | Optional<T>, value?: T) {
    if (hasValue instanceof Optional) {
      this.#data = { ...hasValue.#data };
    } else if (hasValue) {
      this.#data = { hasValue: true, value: value as T };
    } else {
      this.#data = { hasValue: false };
    }
  }

  getValueOr<U>(fallback: U): U extends T ? T : U | T {
    if (this.#data.hasValue) return this.#data.value as U extends T ? T : U | T;
    return fallback as U extends T ? T : U | T;
  }

  getOrSetValue(fallback: T) {
    if (this.#data.hasValue) return this.#data.value;
    this.value = fallback;
    return fallback;
  }

  getOrSetValueComputed(compute: () => T) {
    if (this.#data.hasValue) return this.#data.value;
    const ret = compute();
    this.value = ret;
    return ret;
  }

  set value(value: T) {
    this.#data = { hasValue: true, value: value };
  }

  get value(): Readonly<OptionalData<T>> {
    return this.#data;
  }

  clear() {
    this.#data = { hasValue: false };
  }

  set(value: Optional<T>) {
    this.#data = { ...value.#data };
  }

  getOrSetComputed(compute: () => Optional<T>) {
    if (this.#data.hasValue) return this;
    this.set(compute());
    return this;
  }
}

export function SerialisableOptional<S extends SerialisableConstructor<Serialisable<any>>>(type: S) {
  type V = RemoveOneStaticSerialisable<S>;

  return SerialisableThroughFunction<Optional<V>>((deserialise) => {
    let deserialisedLength = 0;

    // deserialise existence
    deserialise(SerialisableBoolean, (existence) => {
      deserialisedLength += existence.deserialisedLength;
      if (!existence.value) {
        // Does not exist
        return { deserialisedLength, value: new Optional<V>(false) };
      }

      // deserialise value
      deserialise(type, (value) => {
        deserialisedLength += value.deserialisedLength;
        return { deserialisedLength, value: new Optional(true, value.value) };
      }, deserialisedLength);
    }, deserialisedLength);
  }, (value) => {
    if (value.value.hasValue) {
      return new (SerialisableTuple(SerialisableBoolean, type))([true, value.value.value]);
    }
    return new SerialisableBoolean(false);
  });
}
