import { Storer } from "window/Storage/Manager.ts";
import { Optional } from "common/serialisation/optional.ts";

export class BooleanStorer extends Storer<boolean> {
  constructor() {
    super();
  }

  override load(key: string): Optional<boolean> {
    const value = localStorage.getItem(key);
    return value === null ? new Optional(false) : new Optional(true, value === "true");
  }

  override save(key: string, value: Optional<boolean>, prevValue: Optional<boolean>): boolean {
    if (prevValue.value.hasValue === value.value.hasValue && prevValue.getValueOr(undefined) === value.getValueOr(undefined)) return false;
    if (value.value.hasValue) {
      localStorage.setItem(key, `${value.value.value}`);
    } else {
      localStorage.removeItem(key);
    }
    return true;
  }
}
