import type { OutputSettings } from "window/Pages/Output/OutputManager.ts";
import { getPageDimensions } from "window/PdfTools/pageSizes.ts";
import fontkit from "@pdf-lib/fontkit";
import { PDFArray, PDFDict, PDFDocument, PDFName, PDFPage, PDFRawStream, PDFRef } from "pdf-lib";

export type FinalPDFOptions = {
  settings: OutputSettings;
  pages: Uint8Array;
  font: Uint8Array;
  codes: readonly string[];
  text: {
    x: number;
    y: number;
    height: number;
  };
};

export async function renderFinalPDF(options: FinalPDFOptions) {
  const doc = await PDFDocument.create();
  doc.registerFontkit(fontkit);

  const font = await doc.embedFont(options.font, { subset: true });
  const sourceDoc = await PDFDocument.load(options.pages);

  const [front, back] = await doc.embedPdf(sourceDoc, [0, 1]);

  await doc.flush();
  preserveOptionalContent(doc, [front.ref, back.ref], getOffPropertyNames(sourceDoc, sourceDoc.getPages().slice(0, 2)));

  if (!roughlyEqual(front.height / front.width, back.height / back.width)) {
    throw new Error("Pages have different aspect ratios");
  }

  const dimensions = getPageDimensions(options.settings);
  const pageSize = [mmToPoints(dimensions.width), mmToPoints(dimensions.height)] as [number, number];
  const margin = {
    top: mmToPoints(options.settings.margin.top),
    right: mmToPoints(options.settings.margin.right),
    bottom: mmToPoints(options.settings.margin.bottom),
    left: mmToPoints(options.settings.margin.left),
  };
  const voucherScale = Math.min(
    (pageSize[1] - margin.top - margin.bottom) / options.settings.rows / front.height,
    (pageSize[0] - margin.left - margin.right) / options.settings.cols / front.width,
  );
  if (!Number.isFinite(voucherScale) || voucherScale <= 0) {
    throw new Error("Layout leaves no room for vouchers");
  }

  const voucherWidth = front.width * voucherScale;
  const voucherHeight = front.height * voucherScale;
  const cellsPerSheet = options.settings.rows * options.settings.cols;

  for (let sheetStart = 0; sheetStart < options.codes.length; sheetStart += cellsPerSheet) {
    const frontPage = doc.addPage(pageSize);
    const backPage = doc.addPage(pageSize);

    for (let index = 0; index < cellsPerSheet; ++index) {
      const code = options.codes[sheetStart + index];
      if (code === undefined) break;

      const col = index % options.settings.cols;
      const row = Math.floor(index / options.settings.cols);
      const x = margin.left + col * voucherWidth;
      const y = margin.bottom + row * voucherHeight;
      const position = { x, y, width: voucherWidth, height: voucherHeight };

      frontPage.drawPage(front, position);
      backPage.drawPage(back, position);
      backPage.drawText(code, {
        x: x + options.text.x * voucherWidth,
        y: y + options.text.y * voucherHeight,
        size: options.text.height * voucherHeight,
        font,
      });
    }
  }

  return await doc.save();
}

function mmToPoints(mm: number) {
  return mm * 72 / 25.4;
}

function roughlyEqual(a: number, b: number) {
  return Math.abs(a - b) < 0.0001;
}

function getOffPropertyNames(sourceDoc: PDFDocument, pages: readonly PDFPage[]): Set<string> {
  const ret = new Set<string>();

  const ocProperties = sourceDoc.catalog.lookupMaybe(PDFName.of("OCProperties"), PDFDict);
  if (ocProperties === undefined) return ret;

  const defaultConfig = ocProperties.lookupMaybe(PDFName.of("D"), PDFDict);
  if (defaultConfig === undefined) return ret;

  const off = defaultConfig.lookupMaybe(PDFName.of("OFF"), PDFArray);
  if (off === undefined) return ret;

  const offRefs = new Set<PDFRef>();

  for (let i = 0; i < off.size(); ++i) {
    const value = off.get(i);
    if (value instanceof PDFRef) {
      offRefs.add(value);
    }
  }

  for (const page of pages) {
    const properties = page.node.Resources()?.lookupMaybe(PDFName.of("Properties"), PDFDict);

    if (properties === undefined) continue;

    for (const [name, value] of properties.entries()) {
      if (value instanceof PDFRef && offRefs.has(value)) {
        ret.add(name.decodeText());
      }
    }
  }

  return ret;
}

function getEmbeddedOCGs(doc: PDFDocument, ref: PDFRef): Map<string, PDFRef> {
  const object = doc.context.lookup(ref);
  if (!(object instanceof PDFRawStream)) {
    throw new Error("Embedded page is not a PDFRawStream");
  }

  const resources = object.dict.lookup(PDFName.of("Resources"), PDFDict);
  const properties = resources.lookup(PDFName.of("Properties"), PDFDict);

  const result = new Map<string, PDFRef>();

  for (const [name, value] of properties.entries()) {
    if (value instanceof PDFRef) {
      result.set(name.decodeText(), value);
    }
  }

  return result;
}

function preserveOptionalContent(doc: PDFDocument, refs: PDFRef[], offPropertyNames: Set<string>) {
  let groups;
  try {
    groups = refs.map((ref) => getEmbeddedOCGs(doc, ref)).flatMap((group) => [...group.entries()]);
  } catch (e) {
    console.error("Failed to preserve optional content", e);
    return;
  }

  doc.catalog.set(
    PDFName.of("OCProperties"),
    doc.context.obj({
      OCGs: doc.context.obj(groups.map(([, ref]) => ref)),
      D: doc.context.obj({
        BaseState: PDFName.of("ON"),
        OFF: doc.context.obj(groups.filter(([name]) => offPropertyNames.has(name)).map(([, ref]) => ref)),
      }),
    }),
  );
}
