import { TabPanel } from "window/components/TabPanel.tsx";
import { TabItem } from "window/components/TabItem.tsx";

export class TabContainer extends HTMLElement {
  readonly #tabItems = new Map<TabPanel, TabItem>();
  readonly #tabMenu = (
    <div
      style={{
        display: "flex",
        gap: "0",
        alignItems: "end",
        paddingInline: "0.5rem",
        transform: "translateY(1px)",
      }}
    >
    </div>
  ) as HTMLDivElement;
  readonly #content = (
    <div
      style={{
        minWidth: "0",
        minHeight: "0",
        padding: "0.75rem",
        display: "grid",
        gridTemplateRows: "minmax(0, 1fr)",
        border: "1px solid rgb(0 0 0 / 35%)",
        borderRadius: "0.25rem",
      }}
    >
    </div>
  ) as HTMLDivElement;
  #tab: TabPanel | undefined;

  constructor({ children, name }: { name: string; children: readonly [TabPanel, ...TabPanel[]] }) {
    super();
    this.style.minWidth = "0";
    this.style.minHeight = "0";
    this.style.display = "grid";
    this.style.gridTemplateRows = "auto minmax(0, 1fr)";
    this.#tabMenu.replaceChildren(
      ...children.map((tab) =>
        this.#tabItems.getOrInsertComputed(tab, () => <TabItem name={name} tab={tab} ontab-select={({ detail: tab }) => this.tab = tab} /> as TabItem)
      ),
    );
    this.#content.replaceChildren(...children);
    this.replaceChildren(this.#tabMenu, this.#content);
    this.tab = children.find((tab) => tab.label === localStorage.getItem("tab")) ?? children[0];
  }

  get tab() {
    return this.#tab;
  }

  set tab(tab: TabPanel | undefined) {
    if (tab === undefined || tab === this.#tab) return;
    this.#tab?.validate();
    this.#tab = tab;
    for (const currentTab of this.#content.children) {
      if (!(currentTab instanceof TabPanel)) continue;
      const selected = currentTab === tab;
      const item = this.#tabItems.get(currentTab);
      if (item === undefined) continue;
      currentTab.hidden = !selected;
      item.selected = selected;
    }
    localStorage.setItem("tab", tab.label);
  }
}
