export const pageSizes = {
  A6: { width: 105, height: 148 },
  A5: { width: 148, height: 210 },
  A4: { width: 210, height: 297 },
  A3: { width: 297, height: 420 },
  A2: { width: 420, height: 594 },
  RA4: { width: 215, height: 305 },
  RA3: { width: 305, height: 430 },
  RA2: { width: 430, height: 610 },
  SRA4: { width: 225, height: 320 },
  SRA3: { width: 320, height: 450 },
  SRA2: { width: 450, height: 640 },
  Letter: { width: 215.9, height: 279.4 },
  Legal: { width: 215.9, height: 355.6 },
  Tabloid: { width: 279.4, height: 431.8 },
} as const;

export type PageSizeName = keyof typeof pageSizes;

export type PageSetting =
  | {
    readonly pageSize: PageSizeName;
    readonly width?: never;
    readonly height?: never;
  }
  | {
    readonly pageSize?: never;
    readonly width: number;
    readonly height: number;
  };

export function getPageDimensions(settings: PageSetting) {
  if (settings.pageSize !== undefined) return pageSizes[settings.pageSize];
  return { width: settings.width, height: settings.height };
}
