import { Conditional } from "common/conditional.ts";

export type EventMap = {
  [key: string]: unknown;
};

export interface TypedEventEmitter<Events extends EventMap> {
  on<key extends keyof Events & string>(type: key, callback: (event: { detail: Events[key] }) => void): void;
  once<key extends keyof Events & string>(type: key, callback: (event: { detail: Events[key] }) => void): void;
  off<key extends keyof Events & string>(type: key, callback: (event: { detail: Events[key] }) => void): void;
  emit<key extends keyof Events & string>(type: key, args: Events[key]): boolean;

  [Symbol.asyncIterator](): AsyncIterator<Conditional<Events>, never, undefined>;
}

export class EventEmitter<Events extends EventMap> implements TypedEventEmitter<EventMap> {
  et = new EventTarget();
  iterableListeners = new Set<(<key extends keyof Events & string>(key: key, value: Events[key]) => void)>();
  on<key extends keyof Events & string>(type: key, callback: (event: CustomEvent<Events[key]>) => void) {
    return this.et.addEventListener(type as string, callback as EventListener);
  }

  once<key extends keyof Events & string>(type: key, callback: (event: CustomEvent<Events[key]>) => void) {
    return this.et.addEventListener(type as string, callback as EventListener, { once: true });
  }

  off<key extends keyof Events & string>(type: key, callback: (event: CustomEvent<Events[key]>) => void) {
    return this.et.removeEventListener(type as string, callback as EventListener);
  }

  emit<key extends keyof Events & string>(type: key, args: Events[key]) {
    this.iterableListeners.forEach((listener) => listener(type, args));
    return this.et.dispatchEvent(new CustomEvent<Events[key]>(type as string, { detail: args }));
  }

  async *[Symbol.asyncIterator](): AsyncIterator<Conditional<Events>, never, undefined> {
    // I expect to yield when emits
    let defer = Promise.withResolvers<Conditional<Events>>();
    const promises = [defer.promise];
    const handler = <Key extends keyof Events & string>(key: Key, value: Events[Key]) => {
      const resolve = defer.resolve;
      defer = Promise.withResolvers<Conditional<Events>>();
      promises.push(defer.promise);
      resolve({ key, value } as Conditional<Events>);
    };
    this.iterableListeners.add(handler);
    try {
      while (true) {
        yield await promises.shift()!;
      }
    } finally {
      this.iterableListeners.delete(handler);
    }
  }
}
