import { CSSProperty } from "web/CSSProperty.ts";

type Rule = Partial<Record<CSSProperty | `--${string}`, string>>;

type Selector = `${
  | "q"
  | "w"
  | "e"
  | "r"
  | "t"
  | "y"
  | "u"
  | "i"
  | "o"
  | "p"
  | "a"
  | "s"
  | "d"
  | "f"
  | "g"
  | "h"
  | "j"
  | "k"
  | "l"
  | "z"
  | "x"
  | "c"
  | "v"
  | "b"
  | "n"
  | "m"
  | "*"
  | "."
  | "#"
  | ":"}${string}`;

export function makeStyleSheet(
  rules:
    & {
      [K in Selector]?: Rule;
    }
    & {
      [K in `@${string}`]?: Partial<Record<Selector, Rule>>;
    },
) {
  const ret = new CSSStyleSheet();
  for (const selector in rules) {
    if (selector.startsWith("@")) {
      const rule = `${selector} {\n${
        Object.entries<Rule>((rules as Record<string, Record<Selector, Rule>>)[selector]).map(([selector, rule]) => ruleString(selector, rule) + "\n").join("")
      }}`;
      console.log(rule);
      ret.insertRule(rule, ret.cssRules.length);    
    } else {
      ret.insertRule(ruleString(selector, (rules as Record<string, Rule>)[selector]), ret.cssRules.length);
    }
  }
  return ret;
}

function ruleString(selector: string, rule: Rule): string {
  return `${selector} {\n${Object.entries(rule).map(([property, value]) => `${property}: ${value};\n`).join("")}}`;
}
