import { CodesManager } from "window/Pages/Codes/CodesManager.ts";
import { processNonNegativeInteger } from "window/components/Field.tsx";
import { DownloadField, InputField } from "jsx/custom";
import { TabPanel } from "window/components/TabPanel.tsx";
import { ProcessResult } from "window/validation.ts";
import { stringify } from "@std/csv";
import { outputTab } from "window/index.tsx";

export class CodesPage extends TabPanel {
  readonly #list = <div />;
  readonly csvDownloadField = (
    <DownloadField
      downloaded={CodesManager.instance.get("codes.csvDownloaded").getValueOr(false)}
      label="Codes CSV"
      onclick={() => {
        outputTab.vouchersDownloadField.validate({ touched: true });
        this.#downloadCodes();
      }}
    />
  ) as DownloadField;
  readonly #firstField = (
    <InputField
      oncustom-validate={() => {
        this.#lastField.validate();
        this.#formatField.validate();
      }}
      label="First number"
      min="1"
      oninput={() => this.#updateCodes()}
      process={processNonNegativeInteger}
      step="1"
      type="number"
      value={CodesManager.instance.get("codes.first").getValueOr("")}
    />
  ) as InputField<number>;
  readonly #lastField = (
    <InputField
      oncustom-validate={() => this.#formatField.validate()}
      label="Last number"
      min="1"
      oninput={() => this.#updateCodes()}
      process={(value) => this.#processLastNumber(value)}
      step="1"
      type="number"
      value={CodesManager.instance.get("codes.last").getValueOr("")}
    />
  ) as InputField<number>;
  readonly #formatField = (
    <InputField
      label="Format"
      oninput={() => this.#updateCodes()}
      process={(value) => this.#processFormat(value)}
      value={CodesManager.instance.get("codes.format").getValueOr("")}
    />
  ) as InputField<string>;

  constructor() {
    super({ label: "Codes" });
    this.style.minWidth = "0";
    this.style.minHeight = "0";
    this.style.display = "grid";
    this.style.gridTemplateRows = "auto minmax(0, 1fr) auto";
    this.style.gap = "0.5rem";

    this.#renderList();
    this.#updateDownloadButton();

    this.replaceChildren(
      <div className="option-grid" style={{ minWidth: "0" }}>
        {this.#firstField}
        {this.#lastField}
        {this.#formatField}
      </div>,
      <fieldset style={{ minWidth: "0", minHeight: "0", overflow: "auto" }}>
        <legend>Codes</legend>
        {this.#list}
      </fieldset>,
      <div style={{ display: "flex", alignItems: "center", gap: "0.5rem" }}>
        {this.csvDownloadField}
      </div>,
    );
  }

  #updateCodes() {
    CodesManager.instance.setSettings({
      first: this.#firstField.input.value,
      last: this.#lastField.input.value,
      format: this.#formatField.input.value,
    });

    this.#firstField.validate();
    this.#lastField.validate();
    this.#formatField.validate();

    if (this.#firstField.value === undefined || this.#lastField.value === undefined || this.#formatField.value === undefined) {
      CodesManager.instance.clear();
      return;
    }
    CodesManager.instance.update({ format: this.#formatField.value, min: this.#firstField.value, max: this.#lastField.value });

    this.#renderList();
    this.#updateDownloadButton();
  }

  #renderList() {
    this.#list.replaceChildren();
    for (const code of CodesManager.instance.get("codes.codes").getValueOr([])) {
      this.#list.appendChild(<span style={{ display: "block" }}>{code}</span>);
    }
  }

  #updateDownloadButton() {
    this.csvDownloadField.disabled = CodesManager.instance.get("codes.codes").getValueOr([]).length === 0;
    this.csvDownloadField.downloaded = CodesManager.instance.get("codes.csvDownloaded").getValueOr(false);
  }

  #downloadCodes() {
    if (CodesManager.instance.get("codes.codes").getValueOr([]).length === 0) return;

    const csv = stringify(CodesManager.instance.get("codes.codes").getValueOr([]).map((a) => [a]));
    const blob = new Blob([csv], { type: "text/csv" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = "codes.csv";
    link.click();
    CodesManager.instance.set("codes.csvDownloaded", true);
    this.#updateDownloadButton();
    setTimeout(() => URL.revokeObjectURL(url), 0);
  }

  #processLastNumber(value: string): ProcessResult<number> {
    const result = processNonNegativeInteger(value);
    if ("invalid" in result) return result;
    if (this.#firstField.value === undefined) return result;
    if (result.valid < this.#firstField.value) return { invalid: ["must be at least the first number"] };
    if (result.valid - this.#firstField.value + 1 > 10000) return { invalid: ["must create 10000 codes or fewer"] };
    return result;
  }

  #processFormat(value: string): ProcessResult<string> {
    if (this.#lastField.value === undefined) return { valid: value };
    const placeholders = value.match(/(?:\\)|i/g)?.reduce((p, v) => p + (v === "i" ? 1 : 0), 0) ?? 0;
    const required = Math.floor(Math.log10(Math.max(this.#lastField.value, 1))) + 1;
    if (placeholders < required) return { invalid: [`needs at least ${required} i's`] };
    return { valid: value };
  }
}
