import { Field } from "window/components/Field.tsx";
import { Section } from "window/components/Section.tsx";

export function validateDescendants(root: Element, options: { force?: boolean; touched?: boolean } = {}) {
  for (const child of root.children) {
    if (child instanceof Field || child instanceof Section) {
      child.validate(options);
    } else {
      child.querySelectorAll("*").forEach((descendant) => {
        if (descendant instanceof Field || descendant instanceof Section) descendant.validate(options);
      });
    }
  }
}
