import { Optional } from "common/serialisation/optional.ts";

/**
 * Returns a function that will postpone calling until the current operation has finished.
 * Only the most recently postponed operation will be run. Earlier calls will be forgotten.
 * When a call is forgotten, it is resolved with a valueless optional.
 */
export function postponable<Args extends any[], R>(operation: (...args: Args) => Promise<R>): (...args: Args) => Promise<Optional<Awaited<R>>> {
  let operating = false;
  let postponed: PromiseWithResolvers<boolean> | undefined;

  return async (...args: Args) => {
    const deferred = Promise.withResolvers<boolean>();

    if (postponed !== undefined) {
      // Forget the previously postponed call
      postponed.resolve(false);
    }

    if (operating) {
      // postpone this call
      postponed = deferred;
      if (!await deferred.promise) {
        // This call was forgotten
        return new Optional(false);
      }
    }

    operating = true;
    try {
      return new Optional(true, await operation(...args));
    } finally {
      const next = postponed;
      postponed = undefined;
      if (next === undefined) {
        operating = false;
      } else {
        next.resolve(true);
      }
    }
  };
}
