import { Storer } from "window/Storage/Manager.ts";
import { Optional } from "common/serialisation/optional.ts";

export class StringStorer extends Storer<string> {
  constructor() {
    super();
  }
  override load(key: string): Optional<string> {
    const value = localStorage.getItem(key);
    return value === null ? new Optional(false) : new Optional(true, value);
  }
  override save(key: string, value: Optional<string>, prevValue: Optional<string>): boolean {
    if (prevValue.getValueOr(undefined) === value.getValueOr(undefined)) return false;
    if (value.value.hasValue) {
      localStorage.setItem(key, value.value.value);
    } else {
      localStorage.removeItem(key);
    }
    return true;
  }
}
