// deno-lint-ignore-file no-explicit-any
export type SymmetricDifference<A, B> = Omit<A, keyof B> & Omit<B, keyof A>;
export type Replace<T, S extends keyof T, U> = Omit<T, S> & Record<S, U>;
/**
 * class decorator to ensure that the class implements the type statically
 */
export function staticImplements<T extends abstract new (...args: any) => any>() {
  return <U extends T>(_constructor: U, _context: ClassDecoratorContext<U>) => {};
}

export type EmptyObject = { [K in PropertyKey]: never };

// Does T contain anything assignable to U?
export type Contains<T extends any[], U> = T extends [infer A, ...infer R extends any[]] ? A extends U ? true : Contains<R, U> : false;

// Does F appear in S?
export type StringContains<S extends string, F extends string> = S extends `${string}${F}${string}` ? true : false;

// Does T contain anything that is assignable to the type of an earlier member?
export type Duplicates<T extends any[]> = T extends [infer A, ...infer R extends any[]] ? Contains<R, A> extends true ? true : Duplicates<R> : false;
export type DuplicatesWithError<T extends any[]> = T extends [infer A, ...infer R extends any[]]
  ? Contains<R, A> extends true ? [true, A] : DuplicatesWithError<R>
  : false;

export type All<T extends boolean[]> = T extends [infer A extends boolean, ...infer B extends boolean[]] ? A extends true ? All<B> : false : true;
export type Any<T extends boolean[]> = T extends [infer A extends boolean, ...infer B extends boolean[]] ? A extends false ? Any<B> : true : false;

export type IfExtends<A, E, B> = A extends E ? B : A;

export type KeysOfWhere<T, V> = { [K in keyof T]: T[K] extends V ? K : never }[keyof T];
export type KeysOfWhereNot<T, V> = { [K in keyof T]: T[K] extends V ? never : K }[keyof T];

export type RecursiveReadonly<T> = T extends (infer R)[] ? ReadonlyArray<RecursiveReadonly<R>>
  // deno-lint-ignore ban-types
  : T extends Function ? T
  : T extends object ? {
      readonly [K in keyof T]: RecursiveReadonly<T[K]>;
    }
  : T;

export type WritableArrayLike<T> = {
  length: number;
  [n: number]: T;
};

export type Combined<T> =
  & {
    [K in keyof T]: T[K];
  }
  & {};
