import { workerUrl } from "generated/worker-url.ts";
import { postponable } from "common/postponable.ts";
import { GlobalWorkerOptions, PDFPageProxy, RenderTask } from "pdfjs-dist";
import { getContentBoxSize } from "window/components/layout.ts";
import { sleep } from "common/async.ts";

GlobalWorkerOptions.workerSrc = workerUrl;

type RenderedPDFPage = {
  canvas: HTMLCanvasElement;
  context: CanvasRenderingContext2D;
  outputScale: number;
  viewport: ReturnType<PDFPageProxy["getViewport"]>;
};

export class PDFFile extends HTMLElement {
  readonly canvas = (
    <canvas
      style={{
        boxSizing: "border-box",
        display: "block",
        maxWidth: "100%",
        maxHeight: "100%",
        background: "white",
        boxShadow: "0 0 0 1px rgb(0 0 0 / 8%), 0 0.35rem 1rem rgb(0 0 0 / 18%), 0 0.08rem 0.2rem rgb(0 0 0 / 12%)",
      }}
    >
    </canvas>
  ) as HTMLCanvasElement;
  readonly #context: CanvasRenderingContext2D;
  readonly #renderLoadedPage = postponable(async () => {
    await this.renderLoadedPageOp();
    await sleep(0.2); // Don't rerender too frequently
  });
  #optionalContentConfigPromise?: Parameters<PDFPageProxy["render"]>[0]["optionalContentConfigPromise"];
  #page?: PDFPageProxy;
  #renderTask?: RenderTask;

  constructor() {
    super();
    this.style.boxSizing = "border-box";
    this.style.display = "flex";
    this.style.alignItems = "center";
    this.style.justifyContent = "center";
    this.style.width = "100%";
    this.style.height = "100%";
    this.style.padding = "1rem";
    this.style.minWidth = "0";
    this.style.minHeight = "0";
    this.append(this.canvas);

    const context = this.canvas.getContext("2d");
    if (context === null) throw new Error("context is null");
    this.#context = context;

    const resizeObserver = new ResizeObserver(() => this.renderLoadedPage());
    resizeObserver.observe(this);
  }

  set page(page: PDFPageProxy | undefined) {
    this.#page = page;
    if (page === undefined) {
      this.#optionalContentConfigPromise = undefined;
      this.#renderTask?.cancel();
      this.#context.clearRect(0, 0, this.canvas.width, this.canvas.height);
      this.canvas.style.width = "";
      this.canvas.style.height = "";
      this.canvas.removeAttribute("width");
      this.canvas.removeAttribute("height");
      return;
    }
    this.dispatchEvent(new CustomEvent("pdf-page-change", { bubbles: true, detail: page.getViewport({ scale: 1 }) }));
    this.renderLoadedPage();
  }

  get page() {
    return this.#page;
  }

  setOptionalContentConfigPromise(optionalContentConfigPromise: Parameters<PDFPageProxy["render"]>[0]["optionalContentConfigPromise"] | undefined) {
    this.#optionalContentConfigPromise = optionalContentConfigPromise;
    this.renderLoadedPage();
  }

  async renderLoadedPage() {
    await this.#renderLoadedPage();
  }

  protected async renderLoadedPageOp() {
    const rendered = await this.renderPDFPage();
    if (rendered === undefined) return;
    this.commitRenderedPage(rendered);
  }

  protected async renderPDFPage(): Promise<RenderedPDFPage | undefined> {
    if (this.#page === undefined) return;
    const page = this.#page;
    const contentBox = getContentBoxSize(this);
    if (contentBox.width <= 0 || contentBox.height <= 0) return;
    const outputScale = globalThis.devicePixelRatio || 1;
    const unscaledViewport = page.getViewport({ scale: 1 });
    const pageScale = Math.min(
      contentBox.width / unscaledViewport.width,
      contentBox.height / unscaledViewport.height,
    );
    const fittedWidth = Math.max(1, Math.floor(unscaledViewport.width * pageScale));
    const fittedHeight = Math.max(1, Math.floor(unscaledViewport.height * pageScale));
    const viewport = page.getViewport({
      scale: Math.min(
        fittedWidth / unscaledViewport.width,
        fittedHeight / unscaledViewport.height,
      ),
    });

    this.canvas.style.width = `${viewport.width}px`;
    this.canvas.style.height = `${viewport.height}px`;

    const canvas = document.createElement("canvas");
    canvas.width = Math.max(1, Math.floor(viewport.width * outputScale));
    canvas.height = Math.max(1, Math.floor(viewport.height * outputScale));
    const context = canvas.getContext("2d");
    if (context === null) throw new Error("context is null");

    context.fillStyle = "white";
    context.fillRect(0, 0, canvas.width, canvas.height);

    const task = page.render({
      canvas,
      canvasContext: context,
      transform: [
        outputScale,
        0,
        0,
        outputScale,
        0,
        0,
      ],
      viewport,
      optionalContentConfigPromise: this.#optionalContentConfigPromise,
    });
    this.#renderTask = task;

    try {
      await task.promise;
      return { canvas, context, outputScale, viewport };
    } catch (error) {
      if (!(error instanceof Error) || error.name !== "RenderingCancelledException") {
        throw error;
      }
    } finally {
      if (this.#renderTask === task) {
        this.#renderTask = undefined;
      }
    }
  }

  protected commitRenderedPage({ canvas }: RenderedPDFPage) {
    this.canvas.width = canvas.width;
    this.canvas.height = canvas.height;
    this.#context.setTransform(1, 0, 0, 1, 0, 0);
    this.#context.drawImage(canvas, 0, 0);
  }
}
