import { addTypedEvents, EventHandlers } from "web/TypedEventHTMLElement.tsx";

const typedDialogElement = addTypedEvents(HTMLDialogElement);
export class CustomDialog<T extends Record<string, unknown>> extends typedDialogElement<T> {
  private readonly backdrop = (
    <div
      style={{
        inset: "0",
        width: "100vw",
        height: "100vh",
        position: "fixed",
        background: "black",
        opacity: "10%",
        zIndex: "99",
      }}
      popover="manual"
    >
      {this}
    </div>
  );

  constructor(
    { children, style, ...eventHandlers }:
      & EventHandlers<T>
      & {
        children: HTMLElement[];
        style?: Partial<
          CSSStyleDeclaration & {
            [k: `--${string}`]: string;
          }
        >;
      },
  ) {
    super(eventHandlers as any);

    this.popover = "manual";

    for (const key in style) {
      this.style[key as any] = style[key as any]!;
    }
    this.replaceChildren(...children);
    this.addEventListener("keydown", (e) => {
      if (e.key === "Escape") {
        this.close();
      }
    });
  }

  override showModal() {
    document.body.appendChild(this.backdrop);
    this.backdrop.togglePopover(true);
    super.togglePopover(true);
  }

  override close() {
    super.togglePopover(false);
    this.backdrop.togglePopover(false);
    document.body.removeChild(this.backdrop);
  }
}

type AlertEvents = {
  "custom-close": undefined;
};

export class Alert extends CustomDialog<AlertEvents> {
  // HTMLElements
  private alertButton: HTMLElement;
  private readonly alert: HTMLElement;

  constructor(
    { children, alertStyle, dialogStyle, alertTextContent, ...eventHandlers }: {
      children: HTMLElement[];
      alertStyle?: Partial<
        CSSStyleDeclaration & {
          [k: `--${string}`]: string;
        }
      >;
      dialogStyle?: Partial<
        CSSStyleDeclaration & {
          [k: `--${string}`]: string;
        }
      >;
      alertTextContent: string;
    } & EventHandlers<AlertEvents>,
  ) {
    super({ children: [], style: dialogStyle, ...eventHandlers });
    this.alertButton = (
      <button
        onclick={() => {
          this.emit("custom-close", undefined);
          this.close();
        }}
        style={{ height: "20%", fontSize: "2rem" }}
      >
        {alertTextContent}
      </button>
    );
    this.alert = <div style={alertStyle ?? {}}>{...children}</div>;
    this.alertButton.setAttribute("disabled", "true");
    setTimeout(() => {
      this.alertButton.removeAttribute("disabled");
    }, 200);
    this.replaceChildren(this.alert, this.alertButton);
  }
}

type ConfirmEvents = {
  "custom-confirm": boolean;
};

export class Confirm extends CustomDialog<ConfirmEvents> {
  // HTMLElements
  private readonly confirmButton: HTMLButtonElement;
  private readonly denyButton: HTMLButtonElement;

  private readonly confirm: HTMLElement;
  private readonly buttons: HTMLElement;

  constructor(
    { children, confirmStyle, dialogStyle, confirmTextContent, denyTextContent, closeOnConfirm = true, ...eventHandlers }: {
      children: HTMLElement[];
      confirmStyle?: Partial<
        CSSStyleDeclaration & {
          [k: `--${string}`]: string;
        }
      >;
      dialogStyle?: Partial<
        CSSStyleDeclaration & {
          [k: `--${string}`]: string;
        }
      >;
      confirmTextContent: string;
      denyTextContent: string;
      closeOnConfirm?: boolean;
    } & EventHandlers<ConfirmEvents>,
  ) {
    super({ children: [], style: dialogStyle, ...eventHandlers });
    this.confirm = <div style={confirmStyle ?? {}}>{...children}</div> as HTMLDivElement;
    this.confirmButton = (
      <button
        style={{ width: "100%", height: "100%", fontSize: "2rem" }}
        onclick={() => {
          this.emit("custom-confirm", true);
          if (closeOnConfirm) this.close();
        }}
      >
        {confirmTextContent}
      </button>
    ) as HTMLButtonElement;
    this.denyButton = (
      <button
        style={{ width: "100%", height: "100%", fontSize: "2rem" }}
        onclick={() => {
          this.emit("custom-confirm", false);
          this.close();
        }}
      >
        {denyTextContent}
      </button>
    ) as HTMLButtonElement;
    this.buttons = <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr" }}>{this.confirmButton}{this.denyButton}</div> as HTMLDivElement;
    this.confirmButton.setAttribute("disabled", "true");
    this.denyButton.setAttribute("disabled", "true");
    setTimeout(() => {
      this.confirmButton.removeAttribute("disabled");
      this.denyButton.removeAttribute("disabled");
    }, 200);
    this.replaceChildren(this.confirm, this.buttons);
  }
  set confirmDisabled(disable: boolean) {
    this.confirmButton.disabled = disable;
  }
}

type PromptEvents = {
  "custom-prompt": string | null;
};

export class Prompt extends CustomDialog<PromptEvents> {
  // HTMLElements
  private readonly confirmButton: HTMLButtonElement;
  private readonly denyButton: HTMLButtonElement;
  private readonly prompt: HTMLInputElement;
  private readonly response: HTMLElement;

  private readonly buttons: HTMLElement;

  constructor({ children, defaultPromptValue, promptStyle, dialogStyle, confirmTextContent, denyTextContent, ...eventHandlers }: {
    children: HTMLElement[];
    defaultPromptValue?: string;
    promptStyle?: Partial<
      CSSStyleDeclaration & {
        [k: `--${string}`]: string;
      }
    >;
    dialogStyle?: Partial<
      CSSStyleDeclaration & {
        [k: `--${string}`]: string;
      }
    >;
    confirmTextContent: string;
    denyTextContent: string;
  } & EventHandlers<PromptEvents>) {
    super({ children: [], style: dialogStyle, ...eventHandlers });
    this.prompt = <input type="text" value={defaultPromptValue ?? ""}></input> as HTMLInputElement;
    this.response = <div style={promptStyle ?? { display: "flex", flexDirection: "column" }} />;
    this.confirmButton = (
      <button
        onclick={() => {
          this.emit("custom-prompt", this.prompt.value);
          this.close();
        }}
        style={{ fontSize: "2rem" }}
      >
        {confirmTextContent}
      </button>
    ) as HTMLButtonElement;
    this.denyButton = (
      <button
        onclick={() => {
          this.emit("custom-prompt", null);
          this.close();
        }}
        style={{ fontSize: "2rem" }}
      >
        {denyTextContent}
      </button>
    ) as HTMLButtonElement;
    this.buttons = <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr" }}>{this.confirmButton}{this.denyButton}</div>;
    this.response.replaceChildren(...children, this.prompt, this.buttons);
    this.addEventListener("keypress", (e) => {
      if (e.key === "Enter") {
        this.emit("custom-prompt", this.prompt.value);
        this.close();
      }
    });
    this.confirmButton.setAttribute("disabled", "true");
    this.denyButton.setAttribute("disabled", "true");
    setTimeout(() => {
      this.confirmButton.removeAttribute("disabled");
      this.denyButton.removeAttribute("disabled");
    }, 200);
  }

  connectedCallback() {
    this.prompt.focus();
    this.prompt.select();
    this.replaceChildren(this.response);
  }
}

export async function prompt(
  message: string,
  confirmTextContent: string,
  denyTextContent: string,
  initial?: string,
): Promise<string | null> {
  return await new Promise((go) => {
    const prompt = (
      <Prompt
        oncustom-prompt={(e) => {
          go(e.detail);
          prompt.close();
        }}
        dialogStyle={{ display: "flex", flexDirection: "column", justifyContent: "center", fontSize: "2rem" }}
        defaultPromptValue={initial}
        children={[<div>{message}</div>]}
        confirmTextContent={confirmTextContent}
        denyTextContent={denyTextContent}
      />
    ) as Prompt;
    prompt.showModal();
  });
}

export async function alert(message: string, alertTextContent: string): Promise<void> {
  return await new Promise((go) => {
    const alert = (
      <Alert
        oncustom-alert={() => go()}
        dialogStyle={{ display: "flex", flexDirection: "column", justifyContent: "center", fontSize: "2rem" }}
        children={[<div>{message}</div>]}
        alertTextContent={alertTextContent}
      />
    ) as Alert;
    alert.showModal();
  });
}

export async function confirm(message: string, confirmTextContent: string, denyTextContent: string): Promise<boolean> {
  return await new Promise((go) => {
    const confirm = (
      <Confirm
        oncustom-confirm={(e) => {
          go(e.detail);
        }}
        dialogStyle={{ fontSize: "2rem" }}
        children={[<div>{message}</div>]}
        confirmTextContent={confirmTextContent}
        denyTextContent={denyTextContent}
      />
    ) as Confirm;
    setTimeout(() => {
      confirm.showModal();
    }, 0);
  });
}
