import { isArray } from "common/typeNarrow.ts";

import * as JSX from "jsx/type.ts";
export * as JSX from "jsx/type.ts";

function setEventListener<X extends Extract<keyof HTMLElement, `on${string}`>>(
  key: X,
  element: HTMLElement,
  attr: HTMLElement[X],
) {
  element[key] = attr;
}

function isConstructor(obj: Function): obj is { new (...args: any[]): unknown } {
  const descriptor = Object.getOwnPropertyDescriptor(obj, "prototype");
  return descriptor?.writable === false;
}

export function jsx(
  tag:
    | keyof JSX.IntrinsicElements
    | { new (options: Record<string, any>): JSX.Element }
    | ((options: Record<string, any>) => JSX.Element),
  attributes: Record<string, any>,
): JSX.Element {
  if (typeof tag !== "string") {
    if (isConstructor(tag)) {
      return new tag(attributes);
    } else {
      return tag(attributes);
    }
  }

  const element = document.createElement(tag);

  for (const key in attributes) {
    if (key.startsWith("on")) {
      const event = key as Extract<keyof HTMLElement, `on${string}`>;
      setEventListener(event, element, (attributes as unknown as HTMLElement)[event]);
    } else if (key === "children") {
      const children = (attributes as JSX.ElementChildrenAttribute).children;
      if (isArray(children)) {
        element.append(...children);
      } else {
        element.append(children);
      }
    } else if (key === "style") {
      const style = (attributes as { style: CSSStyleDeclaration }).style;
      for (const property in style) {
        if (property.startsWith("--")) {
          element.style.setProperty(property, style[property]);
        } else {
          element.style[property] = style[property];
        }
      }
    } else if (key === "className") {
      element.className = (attributes as { className: string }).className;
    } else if (key === "classList") {
      (attributes as { classList: string[] | DOMTokenList }).classList.forEach((token) => {
        element.classList.add(token);
      });
    } else if (typeof attributes[key] === "boolean") {
      element.toggleAttribute(key, attributes[key]);
    } else {
      element.setAttribute(key, String(attributes[key]));
    }
  }
  return element;
}

export function Fragment(frag: JSX.ElementChildrenAttribute): JSX.ElementChildrenAttribute["children"] {
  return frag.children;
}

export const jsxs = jsx;
