import { addTypedEvents, EventHandlers } from "web/TypedEventHTMLElement.tsx";
import { prefixValidationErrors, ProcessResult, processResultToErrors, ValidationEvents } from "window/validation.ts";
import { validateDescendants } from "window/components/validateDescendants.tsx";
import { ErrorIndicator } from "window/components/ErrorIndicator.tsx";
import { ElementChildrenAttribute } from "jsx/props.ts";

const TypedEventHTMLFieldSetElement = addTypedEvents(HTMLFieldSetElement);

type SectionEvents = ValidationEvents & {
  collapsechange: { collapsed: boolean };
  fieldsetvalidate: undefined;
};

export class Section extends TypedEventHTMLFieldSetElement<SectionEvents> {
  readonly #legendButton = (
    <button
      className="collapse-toggle"
      onclick={() => {
        this.collapsed = !this.collapsed;
        this.emit("collapsechange", { collapsed: this.collapsed });
        if (this.collapsed) this.validate();
      }}
      style={{
        display: "inline-flex",
        alignItems: "center",
        gap: "0.4rem",
        padding: "0.1rem 0.3rem",
        border: "0",
        background: "transparent",
        color: "inherit",
        font: "inherit",
        cursor: "pointer",
      }}
    >
    </button>
  ) as HTMLButtonElement;
  readonly #errorElement = <ErrorIndicator /> as ErrorIndicator;
  readonly #childErrors = new Map<EventTarget, readonly string[]>();
  readonly #process?: () => ProcessResult<unknown>;

  #label!: string; // assigned through `set label`

  hasErrors() {
    return this.#errorElement.errors.length > 0;
  }

  constructor({ children = [], label, collapsed = false, classList = [], process, ...events }:
    & Partial<EventHandlers<SectionEvents> & ElementChildrenAttribute>
    & {
      label: string;
      collapsed?: boolean;
      classList?: readonly string[] | DOMTokenList;
      process?: () => ProcessResult<unknown>;
    }) {
    super(events);
    this.#process = process;
    this.classList.add("collapsible", ...classList);
    this.label = label;
    this.collapsed = collapsed;
    this.replaceChildren(
      <legend style={{ paddingInline: "0.25rem" }}>
        {this.#legendButton}
        {this.#errorElement}
      </legend>,
      ...(Array.isArray(children) ? children : [children]),
    );
    this.addEventListener("focusout", (event) => {
      if (event.relatedTarget instanceof Node && this.contains(event.relatedTarget)) return;
      this.validate();
    });
    this.addEventListener("custom-validate", (event) => {
      if (event.target === this) return;
      if (event.target === null) return;
      event.stopPropagation();
      if (event.detail.length === 0) {
        this.#childErrors.delete(event.target);
      } else {
        this.#childErrors.set(event.target, event.detail);
      }
      this.collate();
    });
  }

  get label() {
    return this.#label;
  }

  set label(value: string) {
    this.#label = value;
    this.#legendButton.textContent = value;
  }

  get collapsed() {
    return this.classList.contains("collapsed");
  }

  set collapsed(value: boolean) {
    this.classList.toggle("collapsed", value);
  }

  validate(options: { force?: boolean; touched?: boolean } = { force: true }) {
    validateDescendants(this, options);
    this.collate();
  }

  private collate() {
    const childErrors = [...this.#childErrors.values()].flat();
    this.#errorElement.errors = childErrors.length === 0 ? this.getOwnErrors() : childErrors;
    this.emit("custom-validate", prefixValidationErrors(this.label, this.#errorElement.errors), { bubbles: true });
  }

  private getOwnErrors() {
    if (this.#process === undefined) return [];
    return processResultToErrors(this.#process());
  }
}
