import { CodesManager } from "window/Pages/Codes/CodesManager.ts";
import { InputManager } from "window/Pages/Input/InputManager.ts";
import { OutputFieldsetId, OutputManager, OutputSettings, PageSizeName, pageSizes } from "window/Pages/Output/OutputManager.ts";
import { postponable } from "common/postponable.ts";
import { processNonNegativeNumber, processPositiveInteger, processPositiveNumber } from "window/components/Field.tsx";
import { DownloadField, InputField, PDFPages, Section } from "jsx/custom";
import { TabPanel } from "window/components/TabPanel.tsx";
import { getDocument, PDFDocumentProxy, PDFPageProxy } from "pdfjs-dist";
import { getPageDimensions, PageSetting } from "window/PdfTools/pageSizes.ts";
import { getContentBoxSize } from "window/components/layout.ts";
import { renderFinalPDF } from "window/PdfTools/renderFinalPDF.ts";
import { FileData, FileStorer } from "window/Storage/FileStorer.ts";
import { syncThen } from "common/async.ts";
import { codesTab, inputTab } from "window/index.tsx";

type PageDimensions = {
  width: number;
  height: number;
};

type OutputSheetMeasurement = {
  sheetScale: number;
  sheetWidth: number;
  sheetHeight: number;
  outputScale: number;
};

type VoucherLayout = {
  margin: {
    top: number;
    right: number;
    bottom: number;
    left: number;
  };
  voucherViewport: ReturnType<PDFPageProxy["getViewport"]>;
  voucherWidth: number;
  voucherHeight: number;
};

const pageCanvasStyle = {
  boxSizing: "border-box",
  display: "block",
  maxWidth: "100%",
  maxHeight: "100%",
  background: "white",
  boxShadow: "0 0 0 1px rgb(0 0 0 / 8%), 0 0.35rem 1rem rgb(0 0 0 / 18%), 0 0.08rem 0.2rem rgb(0 0 0 / 12%)",
};

const pageSlotStyle = {
  boxSizing: "border-box",
  display: "flex",
  alignItems: "center",
  justifyContent: "center",
  width: "100%",
  height: "100%",
  padding: "1rem",
  minWidth: "0",
  minHeight: "0",
};

export class OutputPage extends TabPanel {
  readonly #frontCanvas = <canvas style={pageCanvasStyle}></canvas> as HTMLCanvasElement;
  readonly #backCanvas = <canvas style={pageCanvasStyle}></canvas> as HTMLCanvasElement;
  readonly #frontSheet = <div style={pageSlotStyle}>{this.#frontCanvas}</div> as HTMLDivElement;
  readonly #backSheet = <div style={pageSlotStyle}>{this.#backCanvas}</div> as HTMLDivElement;
  readonly #rowsField = (
    <InputField
      label="Rows"
      min="1"
      oninput={() => this.#updateSettings()}
      process={processPositiveInteger}
      step="1"
      type="number"
      value={this.#numericInputValue(OutputManager.instance.settings.rows)}
    />
  ) as InputField<number>;
  readonly #colsField = (
    <InputField
      label="Columns"
      min="1"
      oninput={() => this.#updateSettings()}
      process={processPositiveInteger}
      step="1"
      type="number"
      value={this.#numericInputValue(OutputManager.instance.settings.cols)}
    />
  ) as InputField<number>;
  readonly #pageSizeInput = (
    <select onchange={() => this.#updatePageSize()}>
      {[
        ...Object.keys(pageSizes).map((value) => <option value={value} selected={OutputManager.instance.settings.pageSize === value}>{value}</option>),
        <option value="Custom" selected={OutputManager.instance.settings.pageSize === undefined}>Custom</option>,
      ]}
    </select>
  ) as HTMLSelectElement;
  readonly #widthField = (
    <InputField
      label="Width"
      min="1"
      oninput={() => {
        this.#pageSizeInput.value = "Custom";
        this.#updateSettings();
      }}
      process={processPositiveNumber}
      step="any"
      type="number"
    />
  ) as InputField<number>;
  readonly #heightField = (
    <InputField
      label="Height"
      min="1"
      oninput={() => {
        this.#pageSizeInput.value = "Custom";
        this.#updateSettings();
      }}
      process={processPositiveNumber}
      step="any"
      type="number"
    />
  ) as InputField<number>;
  readonly #marginTopField = (
    <InputField
      label="Top"
      min="0"
      oninput={() => this.#updateSettings()}
      process={processNonNegativeNumber}
      step="any"
      type="number"
      value={this.#numericInputValue(OutputManager.instance.settings.margin.top)}
    />
  ) as InputField<number>;
  readonly #marginRightField = (
    <InputField
      label="Right"
      min="0"
      oninput={() => this.#updateSettings()}
      process={processNonNegativeNumber}
      step="any"
      type="number"
      value={this.#numericInputValue(OutputManager.instance.settings.margin.right)}
    />
  ) as InputField<number>;
  readonly #marginBottomField = (
    <InputField
      label="Bottom"
      min="0"
      oninput={() => this.#updateSettings()}
      process={processNonNegativeNumber}
      step="any"
      type="number"
      value={this.#numericInputValue(OutputManager.instance.settings.margin.bottom)}
    />
  ) as InputField<number>;
  readonly #marginLeftField = (
    <InputField
      label="Left"
      min="0"
      oninput={() => this.#updateSettings()}
      process={processNonNegativeNumber}
      step="any"
      type="number"
      value={this.#numericInputValue(OutputManager.instance.settings.margin.left)}
    />
  ) as InputField<number>;
  readonly vouchersDownloadField = (
    <DownloadField
      disabled
      downloaded={OutputManager.instance.get("output.pdfDownloaded").getValueOr(false)}
      label="Vouchers PDF"
      onclick={() => {
        codesTab.csvDownloadField.validate({ touched: true });
        this.#downloadPDF();
      }}
    />
  ) as DownloadField;
  readonly #outputOptions = this.#createOutputFieldset("Layout", [
    this.#rowsField,
    this.#colsField,
    <label>
      <span>Page size</span>
      {this.#pageSizeInput}
    </label>,
    this.#widthField,
    this.#heightField,
    this.#createOutputFieldset("Margins", [
      this.#marginTopField,
      this.#marginRightField,
      this.#marginBottomField,
      this.#marginLeftField,
    ], { id: "output-margin-options" }),
  ], { id: "output-options", classNames: ["option-grid"] });

  #inputPDF: PDFDocumentProxy | undefined;
  #inputFrontPage: PDFPageProxy | undefined;
  #inputBackPage: PDFPageProxy | undefined;
  #fontFace: FontFace | undefined;
  #downloading = false;

  constructor() {
    super({ label: "Output" });
    this.style.minWidth = "0";
    this.style.minHeight = "0";
    this.style.display = "grid";
    this.style.gridTemplateRows = "auto minmax(0, 1fr) auto";
    this.style.gap = "0.5rem";

    const initialPageDimensions = getPageDimensions(OutputManager.instance.settings);
    this.#widthField.input.value = this.#numericInputValue(initialPageDimensions.width);
    this.#heightField.input.value = this.#numericInputValue(initialPageDimensions.height);

    const pages = (
      <PDFPages getPageDimensions={() => getPageDimensions(OutputManager.instance.settings)}>
        {this.#frontSheet}
        {this.#backSheet}
      </PDFPages>
    ) as PDFPages;
    OutputManager.instance.on("change", () => pages.updateLayout());

    this.replaceChildren(
      this.#outputOptions,
      pages,
      <div style={{ display: "flex", alignItems: "center", gap: "0.5rem" }}>
        {this.vouchersDownloadField}
      </div>,
    );

    new ResizeObserver(() => this.#renderOutput()).observe(pages);
    CodesManager.instance.on("change", () => {
      OutputManager.instance.set("output.pdfDownloaded", false);
      this.#updateDownloadButton();
      this.#renderOutput();
    });
    InputManager.instance.on("change", (event) => {
      OutputManager.instance.set("output.pdfDownloaded", false);
      if (event.detail.has("input.pages.file") || event.detail.has("input.font.file")) {
        this.#restoreInputFiles();
        return;
      }
      this.#updateDownloadButton();
      this.#renderOutput();
    });
    queueMicrotask(() => this.#restoreInputFiles());
  }

  #getSettingsFromInputs(): OutputSettings {
    const pageSize = this.#pageSizeInput.value as PageSizeName | "Custom";

    return {
      rows: this.#rowsField.input.valueAsNumber,
      cols: this.#colsField.input.valueAsNumber,
      margin: {
        top: this.#marginTopField.input.valueAsNumber,
        right: this.#marginRightField.input.valueAsNumber,
        bottom: this.#marginBottomField.input.valueAsNumber,
        left: this.#marginLeftField.input.valueAsNumber,
      },
      ...(pageSize === "Custom"
        ? {
          width: this.#widthField.input.valueAsNumber,
          height: this.#heightField.input.valueAsNumber,
        }
        : { pageSize }),
    };
  }

  #updateSettings() {
    OutputManager.instance.update(this.#getSettingsFromInputs());
    this.#outputOptions.validate({ force: false });
    this.#updateDownloadButton();
    this.#renderOutput();
  }

  #updatePageSize() {
    const pageSize = this.#pageSizeInput.value as PageSizeName | "Custom";
    if (pageSize !== "Custom") {
      const size = pageSizes[pageSize];
      this.#widthField.input.value = `${size.width}`;
      this.#heightField.input.value = `${size.height}`;
    }
    this.#updateSettings();
  }

  async #downloadPDF() {
    if (this.#hasDownloadBlockingErrors({ force: true })) {
      this.#updateDownloadButton();
      return;
    }

    try {
      this.#downloading = true;
      this.#updateDownloadButton();

      const pagesFile = InputManager.instance.get("input.pages.file").getValueOr(undefined);
      if (pagesFile === undefined) throw new Error("No pages PDF loaded");
      const fontFile = InputManager.instance.get("input.font.file").getValueOr(undefined);
      if (fontFile === undefined) throw new Error("No code font loaded");
      const codes = CodesManager.instance.get("codes.codes").getValueOr([]);
      if (codes.length === 0) throw new Error("No codes generated");

      const pdf = await renderFinalPDF({
        settings: OutputManager.instance.settings,
        pages: new Uint8Array(await syncThen(FileStorer.fileOf(pagesFile), (file) => file.arrayBuffer())),
        font: new Uint8Array(await syncThen(FileStorer.fileOf(fontFile), (file) => file.arrayBuffer())),
        codes,
        text: {
          x: InputManager.instance.get("input.text.x").getValueOr(NaN),
          y: InputManager.instance.get("input.text.y").getValueOr(NaN),
          height: InputManager.instance.get("input.text.height").getValueOr(NaN),
        },
      });
      const buffer = new ArrayBuffer(pdf.byteLength);
      new Uint8Array(buffer).set(pdf);
      const url = URL.createObjectURL(new Blob([buffer], { type: "application/pdf" }));
      const link = document.createElement("a");
      link.href = url;
      link.download = "vouchers.pdf";
      link.click();
      OutputManager.instance.set("output.pdfDownloaded", true);
      setTimeout(() => URL.revokeObjectURL(url), 0);
    } catch (error) {
      console.error(error);
    } finally {
      this.#downloading = false;
      this.#updateDownloadButton();
    }
  }

  async #restoreInputFiles() {
    this.#inputPDF = undefined;
    this.#inputFrontPage = undefined;
    this.#inputBackPage = undefined;

    const tasks = new Array<Promise<unknown>>();

    const pagesFile = InputManager.instance.get("input.pages.file").getValueOr(undefined);
    if (pagesFile !== undefined) {
      tasks.push(this.restorePagesFile(pagesFile));
    }

    const fontFile = InputManager.instance.get("input.font.file").getValueOr(undefined);
    if (fontFile !== undefined) {
      tasks.push(this.restoreFontFile(fontFile));
    }

    this.#updateDownloadButton();

    await Promise.all(tasks);
    await this.#renderOutput();
  }

  private async restoreFontFile(fontFile: FileData) {
    const font = new FontFace(`voucher-font-family`, await syncThen(FileStorer.fileOf(fontFile), (file) => file.arrayBuffer()));
    if (this.#fontFace !== undefined) document.fonts.delete(this.#fontFace);
    document.fonts.add(await font.load());
    this.#fontFace = font;
  }

  private async restorePagesFile(pagesFile: FileData) {
    this.#inputPDF = await getDocument({
      data: new Uint8Array(await syncThen(FileStorer.fileOf(pagesFile), (file) => file.arrayBuffer())),
    }).promise;
    if (this.#inputPDF.numPages === 2) {
      [this.#inputFrontPage, this.#inputBackPage] = await Promise.all([this.#inputPDF.getPage(1), this.#inputPDF.getPage(2)]);
    }
  }

  #updateDownloadButton() {
    this.vouchersDownloadField.disabled = this.#downloading || this.#hasDownloadBlockingErrors();
    this.vouchersDownloadField.downloaded = OutputManager.instance.get("output.pdfDownloaded").getValueOr(false);
  }

  #hasDownloadBlockingErrors({ force = false }: { force?: boolean } = {}) {
    if (force) {
      this.#outputOptions.validate();
      codesTab.validate();
      inputTab.validate();
    }

    return this.#outputOptions.hasErrors() ||
      codesTab.hasErrors({ except: new Set([codesTab.csvDownloadField]) }) ||
      inputTab.hasErrors();
  }

  readonly #renderOutput = postponable(() => this.#renderOutputOp());
  async #renderOutputOp() {
    if (this.#inputFrontPage === undefined || this.#inputBackPage === undefined) return;
    await Promise.all([
      this.#renderSheet(this.#frontSheet, this.#frontCanvas, this.#inputFrontPage, false),
      this.#renderSheet(this.#backSheet, this.#backCanvas, this.#inputBackPage, true),
    ]);
  }

  async #renderSheet(sheet: HTMLDivElement, canvas: HTMLCanvasElement, inputPage: PDFPageProxy, renderCodes: boolean) {
    const settings = OutputManager.instance.settings;
    const measurement = this.#measureOutputSheet(sheet, getPageDimensions(OutputManager.instance.settings));
    if (measurement === undefined) return;

    const { canvas: renderCanvas, context } = this.#createRenderCanvas(measurement);
    const layout = this.#getVoucherLayout(inputPage, settings, measurement);
    if (layout === undefined) return;

    const voucherCanvas = await this.#renderVoucher(inputPage, layout.voucherViewport, measurement.outputScale);
    this.#drawVouchers({ context, voucherCanvas, layout, measurement, settings, renderCodes });
    this.#showRenderedSheet(canvas, renderCanvas, measurement);
  }

  #measureOutputSheet(sheet: HTMLDivElement, { width, height }: PageDimensions): OutputSheetMeasurement | undefined {
    const contentBox = getContentBoxSize(sheet);
    if (contentBox.width <= 0 || contentBox.height <= 0) return;

    const sheetScale = Math.min(contentBox.width / width, contentBox.height / height);
    const sheetWidth = Math.max(1, Math.floor(width * sheetScale));
    const sheetHeight = Math.max(1, Math.floor(height * sheetScale));
    const outputScale = globalThis.devicePixelRatio || 1;
    return { sheetScale, sheetWidth, sheetHeight, outputScale };
  }

  #createRenderCanvas({ sheetWidth, sheetHeight, outputScale }: OutputSheetMeasurement) {
    const renderCanvas = document.createElement("canvas");
    renderCanvas.width = Math.max(1, Math.floor(sheetWidth * outputScale));
    renderCanvas.height = Math.max(1, Math.floor(sheetHeight * outputScale));
    const context = renderCanvas.getContext("2d");
    if (context === null) throw new Error("context is null");

    context.fillStyle = "white";
    context.fillRect(0, 0, renderCanvas.width, renderCanvas.height);
    return { canvas: renderCanvas, context };
  }

  #getVoucherLayout(
    inputPage: PDFPageProxy,
    settings: OutputSettings,
    { sheetScale, sheetWidth, sheetHeight }: OutputSheetMeasurement,
  ): VoucherLayout | undefined {
    const inputViewport = inputPage.getViewport({ scale: 1 });
    const margin = {
      top: settings.margin.top * sheetScale,
      right: settings.margin.right * sheetScale,
      bottom: settings.margin.bottom * sheetScale,
      left: settings.margin.left * sheetScale,
    };
    const voucherScale = Math.min(
      (sheetHeight - margin.top - margin.bottom) / settings.rows / inputViewport.height,
      (sheetWidth - margin.left - margin.right) / settings.cols / inputViewport.width,
    );
    if (!Number.isFinite(voucherScale) || voucherScale <= 0) return;

    const voucherViewport = inputPage.getViewport({ scale: voucherScale });
    const voucherWidth = voucherViewport.width;
    const voucherHeight = voucherViewport.height;
    return { margin, voucherViewport, voucherWidth, voucherHeight };
  }

  #drawVouchers(
    { context, voucherCanvas, layout, measurement, settings, renderCodes }: {
      context: CanvasRenderingContext2D;
      voucherCanvas: HTMLCanvasElement;
      layout: VoucherLayout;
      measurement: OutputSheetMeasurement;
      settings: OutputSettings;
      renderCodes: boolean;
    },
  ) {
    const { margin, voucherWidth, voucherHeight } = layout;
    const { sheetHeight, outputScale } = measurement;
    const codes = CodesManager.instance.get("codes.codes");

    for (let row = 0; row < settings.rows; ++row) {
      for (let col = 0; col < settings.cols; ++col) {
        const code = codes.getValueOr(undefined)?.[row * settings.cols + col];
        if (code === undefined) break;

        const left = margin.left + col * voucherWidth;
        const top = sheetHeight - margin.bottom - (row + 1) * voucherHeight;
        context.drawImage(voucherCanvas, left * outputScale, top * outputScale);

        if (renderCodes) {
          this.#renderCode(context, code, left, top, voucherWidth, voucherHeight, outputScale);
        }
      }
    }
  }

  #showRenderedSheet(canvas: HTMLCanvasElement, renderCanvas: HTMLCanvasElement, { sheetWidth, sheetHeight }: OutputSheetMeasurement) {
    canvas.style.width = `${sheetWidth}px`;
    canvas.style.height = `${sheetHeight}px`;
    canvas.width = renderCanvas.width;
    canvas.height = renderCanvas.height;
    const visibleContext = canvas.getContext("2d");
    if (visibleContext === null) throw new Error("context is null");
    visibleContext.drawImage(renderCanvas, 0, 0);
  }

  async #renderVoucher(inputPage: PDFPageProxy, viewport: ReturnType<PDFPageProxy["getViewport"]>, outputScale: number) {
    const canvas = document.createElement("canvas");
    canvas.width = Math.max(1, Math.floor(viewport.width * outputScale));
    canvas.height = Math.max(1, Math.floor(viewport.height * outputScale));
    const context = canvas.getContext("2d");
    if (context === null) throw new Error("context is null");

    await inputPage.render({
      canvas,
      canvasContext: context,
      transform: [outputScale, 0, 0, outputScale, 0, 0],
      viewport,
    }).promise;
    return canvas;
  }

  #renderCode(
    context: CanvasRenderingContext2D,
    code: string,
    voucherLeft: number,
    voucherTop: number,
    voucherWidth: number,
    voucherHeight: number,
    outputScale: number,
  ) {
    const textPosition = {
      x: InputManager.instance.get("input.text.x").getValueOr(NaN),
      y: InputManager.instance.get("input.text.y").getValueOr(NaN),
    };
    const textHeight = InputManager.instance.get("input.text.height").getValueOr(NaN);
    if (!Number.isFinite(textPosition.x) || !Number.isFinite(textPosition.y) || !Number.isFinite(textHeight) || textHeight <= 0) return;

    context.save();
    context.setTransform(outputScale, 0, 0, outputScale, 0, 0);
    context.fillStyle = "black";
    context.font = `${voucherHeight * textHeight}px ${this.#fontFace?.family ?? "monospace"}`;
    context.textBaseline = "alphabetic";
    context.fillText(
      code,
      voucherLeft + textPosition.x * voucherWidth,
      voucherTop + (1 - textPosition.y) * voucherHeight,
    );
    context.restore();
  }

  #numericInputValue(value: number) {
    return Number.isFinite(value) ? `${value}` : "";
  }

  #createOutputFieldset(legendText: string, children: Node[], { id, classNames = [] }: { id: OutputFieldsetId; classNames?: string[] }) {
    const fieldset = (
      <Section
        classList={classNames}
        collapsed={OutputManager.instance.get(`output.fieldset.${id}.collapsed`).getValueOr(false)}
        label={legendText}
      >
        {children}
      </Section>
    ) as Section;
    fieldset.addEventListener("collapsechange", (event) => {
      if (!(event instanceof CustomEvent)) return;
      OutputManager.instance.set(`output.fieldset.${id}.collapsed`, event.detail.collapsed);
    });
    return fieldset;
  }
}
