import { staticImplements } from "common/types.ts";
import { Deserialised, DeserialiseError, SerialisableConstructor, Serialisation, SerialisationReader, serialisationType } from "common/serialisation.ts";

@staticImplements<SerialisableConstructor<SerialisableByte>>()
export class SerialisableByte {
  static readonly [serialisationType] = "byte";
  constructor(public value: number) {}
  serialise(data: Serialisation): void {
    using extension = data.extend(1);
    extension.value[0] = this.value;
  }
  static readonly serialisedLength = 1;
  readonly serialisedLength = SerialisableByte.serialisedLength;

  static peek(reader: SerialisationReader, offset?: number): Deserialised<SerialisableByte>;
  static peek(reader: SerialisationReader, offset: number, abort: AbortSignal): Promise<Deserialised<SerialisableByte>>;
  static peek(reader: SerialisationReader, offset = 0, abort?: AbortSignal): Deserialised<SerialisableByte> | Promise<Deserialised<SerialisableByte>> {
    if (abort === undefined) {
      return { deserialisedLength: SerialisableByte.serialisedLength, serialisable: new SerialisableByte((reader.peek(1, offset))[0]) };
    }
    return reader.peek(1, offset, abort).then((data) => ({
      deserialisedLength: SerialisableByte.serialisedLength,
      serialisable: new SerialisableByte(data[0]),
    }));
  }
}

