@staticImplements<SerialisableConstructor<SerialisableString>>()
export class SerialisableString {
  static readonly [serialisationType] = "null terminated";
  constructor(public value: string) {}
  serialise(data: Serialisation): void {
    data.expand(this.serialisedLength);
    using extension = data.extend(this.serialisedLength);
    extension.value.set(new TextEncoder().encode(this.value));
    extension.value[extension.value.length - 1] = 0;
  }
  get serialisedLength(): number {
    return new TextEncoder().encode(this.value).byteLength + 1;
  }
  static peek(reader: SerialisationReader, offset?: number): Deserialised<SerialisableString>;
  static peek(reader: SerialisationReader, offset: number, abort: AbortSignal): Promise<Deserialised<SerialisableString>>;
  static peek(reader: SerialisationReader, offset = 0, abort?: AbortSignal) {
    if (abort === undefined) {
      const end = reader.indexOfByte(0, offset);
      if (end === -1) {
        throw new DeserialiseError();
      }
      return {
        deserialisedLength: end - offset + 1,
        serialisable: new SerialisableString(new TextDecoder().decode(reader.peek(end - offset, offset))),
      };
    }

    return reader.indexOfByte(0, offset, abort).then((end) => {
      return {
        deserialisedLength: end - offset + 1,
        serialisable: new SerialisableString(new TextDecoder().decode(reader.peek(end - offset, offset))),
      };
    });
  }
}

