@staticImplements<SerialisableConstructor<SerialisableAll>>()
export class SerialisableAll {
  static readonly [serialisationType] = "everything so far";
  serialise(data: Serialisation): void {
    using extension = data.extend(this.value.byteLength);
    extension.value.set(this.value);
  }
  constructor(public value: Uint8Array<ArrayBuffer>) {}
  get serialisedLength() {
    return this.value.byteLength;
  }
  static peek(reader: SerialisationReader, offset?: number): Deserialised<SerialisableAll>;
  static peek(reader: SerialisationReader, offset: number, abort: AbortSignal): Promise<Deserialised<SerialisableAll>>;
  static peek(reader: SerialisationReader, offset = 0, abort?: AbortSignal) {
    if (abort === undefined) {
      const all = reader.peek(reader.length - offset, offset);
      return {
        deserialisedLength: all.byteLength,
        serialisable: new SerialisableAll(all),
      };
    }
    return reader.peek(reader.length - offset, offset, abort).then((all) => ({
      deserialisedLength: reader.length - offset,
      serialisable: new SerialisableAll(all),
    }));
  }
}
