import { EventHandler } from "web/TypedEventHTMLElement.tsx";
import { Field } from "window/components/Field.tsx";
import { ProcessResult } from "window/validation.ts";
import { Optional } from "common/serialisation/optional.ts";

export class FileField extends Field<File | undefined, File> {
  readonly #input = <input style={{ display: "none" }} type="file" /> as HTMLInputElement;
  readonly #browseButton = <button>Browse...</button> as HTMLButtonElement;
  readonly #clearButton = <button hidden>Clear</button> as HTMLButtonElement;
  readonly #status = <span style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }} /> as HTMLSpanElement;
  readonly #file: Optional<File>;
  readonly #validationError: Optional<string>;

  constructor({ accept, label, "onfile-clear": onFileClear = null, "onfile-select": onFileSelect = null }: {
    accept: string;
    label: string;
    "onfile-clear"?: EventHandler<undefined> | null;
    "onfile-select"?: EventHandler<File> | null;
  }) {
    const file = new Optional<File>(false);
    const validationError = new Optional<string>(false);
    const valueSpan = <span style={{ display: "flex", gridColumn: "2", alignItems: "center", gap: "0.5rem", minWidth: "0" }} />;
    super({
      children: valueSpan,
      getValue: () => file.getValueOr(undefined),
      label,
      process: () => FileField.processFile(file.getValueOr(undefined), validationError.getValueOr(undefined)),
    });

    valueSpan.replaceChildren(
      this.#input,
      this.#browseButton,
      this.#clearButton,
      this.#status,
    );

    this.#file = file;
    this.#validationError = validationError;
    this.#input.accept = accept;

    if (onFileClear !== null) this.addEventListener("file-clear", onFileClear as EventListener);
    if (onFileSelect !== null) this.addEventListener("file-select", onFileSelect as EventListener);

    this.#browseButton.onclick = () => this.#input.click();
    this.#clearButton.onclick = () => {
      this.clearFile();
      this.dispatchEvent(new CustomEvent<undefined>("file-clear"));
    };
    this.#input.onchange = () => {
      const selectedFile = this.#input.files?.[0];
      if (selectedFile === undefined) return;
      this.setFile(selectedFile);
      this.#input.value = "";
      this.dispatchEvent(new CustomEvent<File>("file-select", { detail: selectedFile }));
    };
  }

  get file() {
    return this.#file.value;
  }

  setFile(file: File | undefined) {
    if (file === undefined) {
      this.#file.clear();
    } else {
      this.#file.value = file;
    }
    this.setStoredFilename(file?.name ?? "");
    this.#validationError.clear();
    this.validate({ force: true });
  }

  setValidationError(message: string | undefined) {
    if (message === undefined) {
      this.#validationError.clear();
    } else {
      this.#validationError.value = message;
    }
    this.validate({ force: true });
  }

  private setStoredFilename(filename: string) {
    this.#status.textContent = filename;
    this.#clearButton.hidden = filename === "";
  }

  private clearFile() {
    this.#file.clear();
    this.#validationError.clear();
    this.setStoredFilename("");
    this.validate({ force: true });
  }

  private static processFile(file: File | undefined, validationError: string | undefined): ProcessResult<File> {
    if (validationError !== undefined) return { invalid: [validationError] };
    if (file === undefined) return { invalid: ["required"] };
    return { valid: file };
  }
}
