import { PDFFile } from "window/components/PDFFile.tsx";
import { PDFPageProxy } from "pdfjs-dist";

export class PDFFileWithOverlay extends PDFFile {
  text = "";
  textPosition = { x: 0, y: 0 };
  textHeight = 0;
  fontFamily = "monospace";
  markerColor = "#ff0000";
  markerVisible = true;

  protected override async renderLoadedPageOp() {
    const rendered = await this.renderPDFPage();
    if (rendered === undefined) return;
    this.renderText(rendered.context, rendered.viewport, rendered.outputScale);
    this.renderMarker(rendered.context, rendered.viewport, rendered.outputScale);
    this.commitRenderedPage(rendered);
  }

  #getFont(fontSize: number) {
    return `${fontSize}px ${this.fontFamily}`;
  }

  private renderText(
    context: CanvasRenderingContext2D,
    viewport: ReturnType<PDFPageProxy["getViewport"]>,
    outputScale: number,
  ) {
    if (
      this.text === "" ||
      !Number.isFinite(this.textPosition.x) ||
      !Number.isFinite(this.textPosition.y) ||
      !Number.isFinite(this.textHeight) ||
      this.textHeight <= 0
    ) return;

    const fontSize = viewport.height * this.textHeight;
    const x = viewport.width * this.textPosition.x;
    const y = viewport.height * (1 - this.textPosition.y);

    context.save();
    context.setTransform(outputScale, 0, 0, outputScale, 0, 0);
    context.fillStyle = "black";
    context.font = this.#getFont(fontSize);
    context.textBaseline = "alphabetic";
    context.fillText(this.text, x, y);
    context.restore();
  }

  private renderMarker(
    context: CanvasRenderingContext2D,
    viewport: ReturnType<PDFPageProxy["getViewport"]>,
    outputScale: number,
  ) {
    if (!this.markerVisible) return;
    if (!Number.isFinite(this.textPosition.x) || !Number.isFinite(this.textPosition.y) || !Number.isFinite(this.textHeight) || this.textHeight <= 0) return;

    const x = viewport.width * this.textPosition.x;
    const baselineY = viewport.height * (1 - this.textPosition.y);
    const fontSize = viewport.height * this.textHeight;

    context.save();
    context.setTransform(outputScale, 0, 0, outputScale, 0, 0);
    context.font = this.#getFont(fontSize);
    const metrics = context.measureText("X");
    const ascent = Math.max(1, metrics.actualBoundingBoxAscent || fontSize * 0.72);
    const descent = Math.max(0, metrics.actualBoundingBoxDescent || 0);
    const topY = baselineY - ascent;
    const bottomY = baselineY + descent;
    const height = ascent + descent;
    const capWidth = height * 0.75;
    const lineWidth = Math.max(1, height * 0.05);
    const capOffset = lineWidth / 2;

    context.strokeStyle = this.markerColor;
    context.lineWidth = lineWidth;
    context.beginPath();
    context.moveTo(x, topY);
    context.lineTo(x, bottomY);
    context.moveTo(x - capWidth / 2, topY - capOffset);
    context.lineTo(x + capWidth / 2, topY - capOffset);
    context.moveTo(x - capWidth / 2, bottomY + capOffset);
    context.lineTo(x + capWidth / 2, bottomY + capOffset);
    context.stroke();
    context.restore();
  }
}
