import { FileStorage } from "window/Storage/FileStorage.ts";
import { FileStorer } from "window/Storage/FileStorer.ts";
import { Manager } from "window/Storage/Manager.ts";
import { BooleanStorer } from "window/Storage/BooleanStorer.ts";
import { NumberStorer } from "window/Storage/NumberStorer.ts";
import { StringStorer } from "window/Storage/StringStorer.ts";

const inputFiles = new FileStorage("voucher-maker-input", "files");

const inputStore = {
  input: {
    text: {
      value: new StringStorer(),
      x: new NumberStorer(),
      y: new NumberStorer(),
      height: new NumberStorer(),
    },
    marker: {
      color: new StringStorer(),
      visible: new BooleanStorer(),
    },
    pages: {
      file: new FileStorer(inputFiles),
    },
    font: {
      file: new FileStorer(inputFiles),
    },
    fieldset: {
      "page-options": {
        collapsed: new BooleanStorer(),
      },
      "text-options": {
        collapsed: new BooleanStorer(),
      },
      "text-code-options": {
        collapsed: new BooleanStorer(),
      },
      "text-position-options": {
        collapsed: new BooleanStorer(),
      },
      "text-font-options": {
        collapsed: new BooleanStorer(),
      },
      "text-marker-options": {
        collapsed: new BooleanStorer(),
      },
    },
  },
};

export class InputManager extends Manager<typeof inputStore> {
  static readonly instance = new InputManager();

  private constructor() {
    super(inputStore);
  }
}
