export type EventHandler<T> = (event: CustomEvent<T>) => void;
type AllEvents<T extends Record<string, unknown>> = HTMLElementEventMap & { [K in string & keyof T]: CustomEvent<T[K]> };

type GConstructor<T = {}> = new (...args: any[]) => T;

/**
 * extend HTMLElement, and have typed event members set up
 */
export function addTypedEvents<E extends GConstructor<HTMLElement>>(base: E) {
  class TypedEventElement<T extends Record<string, unknown>> extends (base as typeof HTMLElement) {
    override addEventListener<E extends string & keyof AllEvents<T>>(
      type: E,
      listener: ((this: typeof this, ev: AllEvents<T>[E]) => void) | { handleEvent(event: AllEvents<T>[E]): void } | null,
      options?: boolean | AddEventListenerOptions | undefined,
    ): void {
      super.addEventListener(type, listener as EventListenerOrEventListenerObject, options);
    }

    override removeEventListener<E extends string & keyof AllEvents<T>>(
      type: E,
      listener: ((this: typeof this, ev: AllEvents<T>[E]) => void) | { handleEvent(event: AllEvents<T>[E]): void } | null,
      options?: boolean | AddEventListenerOptions | undefined,
    ): void {
      super.removeEventListener(type, listener as EventListenerOrEventListenerObject, options);
    }

    constructor(props: EventHandlers<T> = {}) {
      super();

      for (const event in props) {
        if (event.startsWith("on")) {
          (this as any)[event] = props[event as any] ?? null;
          this.addEventListener(event.slice(2), (e) => (this as any)[event]?.(e));
        }
      }
    }
    emit<E extends string & keyof T>(type: E, detail: T[E], options?: Omit<CustomEventInit<T[E]>, "detail">) {
      (this as any as HTMLElement).dispatchEvent(new CustomEvent<T[E]>(type, { detail, ...options }));
    }
  }
  return TypedEventElement as new <T extends Record<string, unknown>>(props?: EventHandlers<T>) => InstanceType<typeof TypedEventElement<T>> & InstanceType<E>;
}

export type EventHandlers<R extends Record<string, unknown>> =
  & {
    [K in string & keyof R as `on${K}`]?: null | EventHandler<R[K]>;
  }
  & {
    [K in keyof HTMLElementEventMap as `on${K}`]?: null | ((event: HTMLElementEventMap[K]) => void);
  };

export const TypedEventHTMLElement = addTypedEvents(HTMLElement);
