import { EventHandlers, TypedEventHTMLElement } from "web/TypedEventHTMLElement.tsx";
import { prefixValidationErrors, ProcessResult, processResultToErrors, ValidationEvents } from "window/validation.ts";
import { ErrorIndicator } from "window/components/ErrorIndicator.tsx";
import { ElementChildrenAttribute } from "jsx/props.ts";

export type FieldEvents<Value> = ValidationEvents & {
  "custom-change": Value;
};

export class Field<Raw = string, Value = Raw> extends TypedEventHTMLElement<FieldEvents<Value>> {
  readonly #labelElement = <span className="field-label" /> as HTMLSpanElement;
  readonly #labelText = <span /> as HTMLSpanElement;
  readonly #errorElement = <ErrorIndicator /> as ErrorIndicator;
  readonly #valueElement = <span className="field-value" /> as HTMLSpanElement;
  readonly #getValue: () => Raw;
  readonly #process: (value: Raw) => ProcessResult<Value>;

  #label = "";
  #touched = false;
  #value: Value | undefined;
  get value() {
    return this.#value;
  }
  private set value(value: Value | undefined) {
    this.#value = value;
  }

  hasError() {
    return this.#errorElement.errors.length > 0;
  }

  constructor({ children = [], getValue, label, process, ...events }:
    & Partial<EventHandlers<FieldEvents<Value>>>
    & Partial<ElementChildrenAttribute>
    & {
      getValue: () => Raw;
      label: string;
      process?: (value: Raw) => ProcessResult<Value>;
    }) {
    super(events as EventHandlers<FieldEvents<Value>>);
    this.#getValue = getValue;
    this.#process = process ?? ((value) => ({ valid: value as unknown as Value }));
    this.label = label;
    this.#labelElement.replaceChildren(this.#labelText, this.#errorElement);
    this.#valueElement.replaceChildren(...(Array.isArray(children) ? children : [children]));
    super.replaceChildren(this.#labelElement, this.#valueElement);
    this.addEventListener("focusout", () => this.validate({ force: true }));
    this.addEventListener("input", () => this.validate({ touched: true }));
    this.addEventListener("change", () => this.validate({ touched: true }));
  }

  override replaceChildren(...nodes: (Node | string)[]): void {
    this.#valueElement.replaceChildren(...nodes);
  }

  get label() {
    return this.#label;
  }

  set label(value: string) {
    this.#label = value;
    this.#labelText.textContent = value;
  }

  validate({ force = false, touched = false }: { force?: boolean; touched?: boolean } = {}) {
    this.#touched ||= touched || force;
    const result = this.#process(this.#getValue());
    if ("valid" in result) {
      this.value = result.valid;
      this.#errorElement.errors = [];
      this.emit("custom-change", result.valid);
    } else {
      this.value = undefined;
      this.#errorElement.errors = this.#touched ? processResultToErrors(result) : [];
    }
    this.emit("custom-validate", prefixValidationErrors(this.label, this.#errorElement.errors), { bubbles: true });
  }
}

export function processRequiredNumber(value: string): ProcessResult<number> {
  const number = Number(value);
  if (value === "" || !Number.isFinite(number)) return { invalid: ["required"] };
  return { valid: number };
}

export function processPositiveNumber(value: string): ProcessResult<number> {
  const number = Number(value);
  if (value === "") return { invalid: ["required"] };
  if (!Number.isFinite(number) || number <= 0) return { invalid: ["must be more than 0"] };
  return { valid: number };
}

export function processPositiveInteger(value: string): ProcessResult<number> {
  const result = processPositiveNumber(value);
  if ("invalid" in result) return result;
  if (!Number.isInteger(result.valid)) return { invalid: ["must be a whole number"] };
  return result;
}

export function processNonNegativeInteger(value: string): ProcessResult<number> {
  const result = processNonNegativeNumber(value);
  if ("invalid" in result) return result;
  if (!Number.isInteger(result.valid)) return { invalid: ["must be a whole number"] };
  return result;
}

export function processNonNegativeNumber(value: string): ProcessResult<number> {
  const number = Number(value);
  if (value === "") return { invalid: ["required"] };
  if (!Number.isFinite(number) || number < 0) return { invalid: ["must be 0 or more"] };
  return { valid: number };
}

export function processFraction(value: string): ProcessResult<number> {
  const number = Number(value);
  if (value === "") return { invalid: ["required"] };
  if (!Number.isFinite(number) || number < 0) return { invalid: ["must be 0 or more"] };
  if (number > 1) return { invalid: ["must be 1 or less"] };
  return { valid: number };
}
