export class FileStorage {
  readonly #database: Promise<IDBDatabase | undefined>;
  readonly #databaseName: string;
  readonly #storeName: string;

  constructor(databaseName: string, storeName: string) {
    this.#databaseName = databaseName;
    this.#storeName = storeName;
    this.#database = this.open();
  }

  async set(key: string, file: File) {
    const store = await this.getObjectStore("readwrite");
    if (store === undefined) return;
    await requestToPromise(store.put(file, key));
  }

  async get(key: string) {
    const store = await this.getObjectStore();
    if (store === undefined) {
      throw new Error(`Cannot load storage for key ${key}`);
    }
    const file = await requestToPromise(store.get(key));
    if (file instanceof File) return file;
    throw new Error(`No file with key ${key} in storage`);
  }

  async delete(key: string) {
    const store = await this.getObjectStore("readwrite");
    if (store === undefined) return;
    await requestToPromise(store.delete(key));
  }

  private async getObjectStore(mode?: IDBTransactionMode) {
    const database = await this.#database;
    return database?.transaction(this.#storeName, mode).objectStore(this.#storeName);
  }

  private async open() {
    if (globalThis.indexedDB === undefined) return;

    try {
      const request = indexedDB.open(this.#databaseName, 1);
      request.onupgradeneeded = () => request.result.createObjectStore(this.#storeName);
      return await requestToPromise(request);
    } catch (error) {
      console.error(error);
    }
  }
}

function requestToPromise<T>(request: IDBRequest<T>) {
  return new Promise<T>((resolve, reject) => {
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}
