export class ErrorIndicator extends HTMLSpanElement {
  constructor() {
    super();
    this.style.visibility = "hidden";
    this.style.cursor = "help";
    this.style.lineHeight = "1";
    this.textContent = "⚠️";
  }

  #errors: readonly string[] = [];

  set errors(value: readonly string[]) {
    this.#errors = value;
    this.style.visibility = value.length === 0 ? "hidden" : "visible";
    this.title = value.join("\n");
  }

  get errors() {
    return this.#errors;
  }
}
