import { Manager } from "window/Storage/Manager.ts";
import { BooleanStorer } from "window/Storage/BooleanStorer.ts";
import { NumberStorer } from "window/Storage/NumberStorer.ts";
import { StringStorer } from "window/Storage/StringStorer.ts";
import { PageSetting, PageSizeName, pageSizes } from "window/PdfTools/pageSizes.ts";

export { pageSizes } from "window/PdfTools/pageSizes.ts";
export type { PageSizeName } from "window/PdfTools/pageSizes.ts";

export type OutputSettings =
  & {
    readonly rows: number;
    readonly cols: number;
    readonly margin: {
      readonly top: number;
      readonly right: number;
      readonly bottom: number;
      readonly left: number;
    };
  }
  & PageSetting;

const outputStore = {
  output: {
    rows: new NumberStorer(),
    cols: new NumberStorer(),
    pageSize: new StringStorer(),
    width: new NumberStorer(),
    height: new NumberStorer(),
    margin: {
      top: new NumberStorer(),
      right: new NumberStorer(),
      bottom: new NumberStorer(),
      left: new NumberStorer(),
    },
    pdfDownloaded: new BooleanStorer(),
    fieldset: {
      "output-options": {
        collapsed: new BooleanStorer(),
      },
      "output-margin-options": {
        collapsed: new BooleanStorer(),
      },
    },
  },
};

export type OutputFieldsetId = keyof typeof outputStore["output"]["fieldset"];

export class OutputManager extends Manager<typeof outputStore> {
  static readonly instance = new OutputManager();

  private constructor() {
    super(outputStore);
  }

  get settings(): OutputSettings {
    return this.getStoredSettings();
  }

  update(settings: OutputSettings) {
    this.batch(() => {
      this.set("output.pdfDownloaded", false);
      this.set("output.rows", settings.rows);
      this.set("output.cols", settings.cols);
      if (settings.pageSize !== undefined) {
        this.set("output.pageSize", settings.pageSize);
        this.set("output.width", NaN);
        this.set("output.height", NaN);
      } else {
        this.set("output.pageSize", "Custom");
        this.set("output.width", settings.width);
        this.set("output.height", settings.height);
      }
      this.set("output.margin.top", settings.margin.top);
      this.set("output.margin.right", settings.margin.right);
      this.set("output.margin.bottom", settings.margin.bottom);
      this.set("output.margin.left", settings.margin.left);
    });
  }

  private getStoredSettings(): OutputSettings {
    const common = {
      rows: this.get("output.rows").getValueOr(NaN),
      cols: this.get("output.cols").getValueOr(NaN),
      margin: {
        top: this.get("output.margin.top").getValueOr(NaN),
        right: this.get("output.margin.right").getValueOr(NaN),
        bottom: this.get("output.margin.bottom").getValueOr(NaN),
        left: this.get("output.margin.left").getValueOr(NaN),
      },
    };
    const pageSetting = this.getPageSetting();
    return { ...common, ...pageSetting };
  }

  private getPageSetting(): { pageSize: PageSizeName } | { width: number; height: number } {
    const value = this.get("output.pageSize").getValueOr("");
    if (value in pageSizes) return { pageSize: value as PageSizeName };
    if (value === "Custom") {
      return {
        width: this.get("output.width").getValueOr(NaN),
        height: this.get("output.height").getValueOr(NaN),
      };
    }
    return { pageSize: "A4" };
  }
}
