import { once } from "common/async.ts";
import { makeStyleSheet } from "web/makeStyleSheet.ts";

const style = makeStyleSheet({
  "div": {
    "color": "black",
  },
  "div.menu": {
    "background": "rgba(255, 255, 255, 0.95)",
    "box-shadow": "0 0 8px 8px #0003, 0 0 0 1px #0008",
    "padding": "3px",
    "border-radius": "3px",
  },

  "div.menu:hover": {
    "background": "rgba(255, 255, 255, 1)",
  },

  "div.menu>div": {
    "min-width": "3rem",
    "cursor": "pointer",
    "padding": "0.25em 0.5em",
    "border-radius": "3px",
  },

  "div.menu>div:hover": {
    "background": "hsla(120, 100%, 25%, 0.2)",
  },
});

type ContextMenuEventMap = HTMLElementEventMap & { "select-label": CustomEvent<number> };

export class ContextMenu extends HTMLElement {
  private labels: readonly [string, ...string[]];
  #open = false;
  private menu = <div className="menu"></div>;
  top: number;
  left: number;

  override addEventListener<K extends keyof ContextMenuEventMap>(
    type: K,
    listener: (this: ContextMenu, ev: ContextMenuEventMap[K]) => any,
    options?: boolean | AddEventListenerOptions | undefined,
  ) {
    super.addEventListener(type, listener as EventListenerOrEventListenerObject, options);
  }

  override removeEventListener<K extends keyof ContextMenuEventMap>(
    type: K,
    listener: (this: ContextMenu, ev: ContextMenuEventMap[K]) => any,
    options?: boolean | EventListenerOptions | undefined,
  ) {
    super.removeEventListener(type, listener as EventListenerOrEventListenerObject, options);
  }

  "onselect-label": ((this: GlobalEventHandlers, ev: CustomEvent<number>) => any) | null = null;

  constructor(
    props: {
      left: number;
      top: number;
      children: readonly [string, ...string[]];
      onclose?: (this: GlobalEventHandlers, ev: Event) => void;
      "onselect-label"?: (this: GlobalEventHandlers, ev: CustomEvent<number>) => void;
    },
  ) {
    super();
    this.labels = props.children;
    this.top = props.top;
    this.left = props.left;
    this.style.margin = "0";
    this.style.overflow = "visible";
    this.style.background = "none";
    this.style.border = "0";
    this.popover = "manual";

    this.onclose = props.onclose ?? null;
    this["onselect-label"] = props["onselect-label"] ?? null;
  }

  get open() {
    return this.#open;
  }

  connectedCallback() {
    this.showPopover();
    this.#open = true;
    currentContextMenu?.close();
    currentContextMenu = this;

    this.style.position = "absolute";
    this.style.zIndex = "100";
    const shadow = this.attachShadow({ "mode": "open" });
    shadow.adoptedStyleSheets.push(style);
    this.appendChild(shadow);
    shadow.appendChild(this.menu);

    once(document, "click", () => {
      this.close();
    });

    for (let i = 0; i < this.labels.length; ++i) {
      this.menu.appendChild(
        <div
          onclick={() => {
            const event = new CustomEvent("select", { detail: i });
            this["onselect-label"]?.(event);
            this.dispatchEvent(event);
            this.remove();
          }}
        >
          {this.labels[i]}
        </div>,
      );
    }

    // calculate if the context menu will be rendered off the screen
    const rect = this.getBoundingClientRect();
    const { innerWidth, innerHeight } = window;

    let left = this.left;
    let top = this.top;

    if (left + rect.width > innerWidth) left -= rect.width;
    if (top + rect.height > innerHeight) top -= rect.height;

    this.style.left = `${left}px`;
    this.style.top = `${top}px`;
  }

  disconnectedCallback() {
    this.#open = false;
    const event = new Event("close");
    this.onclose?.(event);
    this.dispatchEvent(event);
  }

  close() {
    this.remove();
    currentContextMenu = null;
  }
}

let currentContextMenu: ContextMenu | null = null;

export function getCurrentContextMenu() {
  return currentContextMenu;
}
