export type Size = {
  width: number;
  height: number;
};

export function getContentBoxSize(element: HTMLElement): Size {
  const style = getComputedStyle(element);
  return {
    width: element.clientWidth - pixelValue(style.paddingLeft) - pixelValue(style.paddingRight),
    height: element.clientHeight - pixelValue(style.paddingTop) - pixelValue(style.paddingBottom),
  };
}

function pixelValue(value: string) {
  const number = parseFloat(value);
  return Number.isFinite(number) ? number : 0;
}
